                        !hmatel = h2a_vvvv(a,b,d,e)
                        hmatel = h2a_vvvv(e,d,b,a)
                        hmatel1 = 0.0d0; hmatel2 = 0.0d0; hmatel3 = 0.0d0; hmatel4 = 0.0d0;
                        if (b==e) hmatel1 = h1a_vv(d,a)
                        if (a==e) hmatel2 = -h1a_vv(d,b)
