                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,c,i,k/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        e = t4_excits_buff(jdet,2); l = t4_excits_buff(jdet,5); m = t4_excits_buff(jdet,6);
                        ! compute < ijkabc | h2a(ooov) | lmikaebc >
                        !hmatel = h2a_ooov(l,m,j,e)
                        hmatel = h2a_ooov(l,m,j,e)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
                     end if
                  end do
                  !$omp end do
                  !$omp end parallel
                  !!!! END OMP PARALLEL SECTION !!!!
                  !!! BCDKL LOOP !!!
                  call sort_pspace(t4_excits_buff, t4_amps_buff, n4aaaa, 5, (/2,3,4,7,8/), kdims, kchain, nblock, block_key, block_off)
                  !!!! BEGIN OMP PARALLEL SECTION !!!!
                  !$omp parallel shared(resid,&
                  !$omp t3a_excits,t4_excits_buff,&
                  !$omp t3a_amps,t4_amps_buff,&
                  !$omp nblock,block_key,block_off,kdims,kchain,&
                  !$omp H2A_ooov,&
                  !$omp noa,nua,n3aaa),&
                  !$omp private(hmatel,a,b,c,d,i,j,k,l,e,f,m,n,idet,jdet,&
                  !$omp idx)
                  !$omp do schedule(static)
                  do idet = 1, n3aaa
                     a = t3a_excits(idet,1); b = t3a_excits(idet,2); c = t3a_excits(idet,3);
                     i = t3a_excits(idet,4); j = t3a_excits(idet,5); k = t3a_excits(idet,6);
                     ! (1)
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,c,i,j/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        d = t4_excits_buff(jdet,1); l = t4_excits_buff(jdet,5); m = t4_excits_buff(jdet,6);
                        ! compute < ijkabc | h2a(ooov) | lmijdabc >
                        !hmatel = h2a_ooov(l,m,k,d)
                        hmatel = h2a_ooov(l,m,k,d)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
                     end if
                     ! (ik)
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,c,j,k/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        d = t4_excits_buff(jdet,1); l = t4_excits_buff(jdet,5); m = t4_excits_buff(jdet,6);
                        ! compute < ijkabc | h2a(ooov) | lmjkdabc >
                        !hmatel = h2a_ooov(l,m,i,d)
                        hmatel = h2a_ooov(l,m,i,d)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
                     end if
                     ! (jk)
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,c,i,k/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        d = t4_excits_buff(jdet,1); l = t4_excits_buff(jdet,5); m = t4_excits_buff(jdet,6);
                        ! compute < ijkabc | h2a(ooov) | lmikdabc >
                        !hmatel = -h2a_ooov(l,m,j,d)
                        hmatel = -h2a_ooov(l,m,j,d)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
                     end if
                  end do
                  !$omp end do
                  !$omp end parallel
                  !!!! END OMP PARALLEL SECTION !!!!
                  ! deallocate sorting arrays
                  deallocate(block_key,block_off)
                  ! deallocate t4 buffer arrays
                  deallocate(t4_amps_buff,t4_excits_buff)

                  !!!! -0.0833333 * H.ab.ooov(mnkf) * T.aaab(abcfijmn) -> abcijk
                  ! allocate and copy over t4b arrays
                  allocate(t4_amps_buff(n4aaab),t4_excits_buff(n4aaab,8))
                  t4_amps_buff(:) = t4b_amps(:)
                  t4_excits_buff(:,:) = t4b_excits(:,:)
                  ! allocate sorting arrays (can be reused for each permutation)
                  kdims(1:5) = (/nua,nua,nua,noa,noa/)
                  kchain(1:5) = (/.false.,.true.,.true.,.false.,.true./)
                  !!! ABCIJ LOOP !!!
                  call sort_pspace(t4_excits_buff, t4_amps_buff, n4aaab, 5, (/1,2,3,5,6/), kdims, kchain, nblock, block_key, block_off)
                  !!!! BEGIN OMP PARALLEL SECTION !!!!
                  !$omp parallel shared(resid,&
                  !$omp t3a_excits,t4_excits_buff,&
                  !$omp t3a_amps,t4_amps_buff,&
                  !$omp nblock,block_key,block_off,kdims,kchain,&
                  !$omp H2B_ooov,&
                  !$omp noa,nua,nob,nub,n3aaa),&
                  !$omp private(hmatel,a,b,c,d,i,j,k,l,e,f,m,n,g,o,idet,jdet,&
                  !$omp idx)
                  !$omp do schedule(static)
                  do idet = 1, n3aaa
                     a = t3a_excits(idet,1); b = t3a_excits(idet,2); c = t3a_excits(idet,3);
                     i = t3a_excits(idet,4); j = t3a_excits(idet,5); k = t3a_excits(idet,6);
                     ! (1)
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,c,i,j/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        g = t4_excits_buff(jdet,4); n = t4_excits_buff(jdet,7); o = t4_excits_buff(jdet,8);
                        ! compute < ijkabc | h2b(ooov) | ijno~abcg~ >
                        !hmatel = -h2b_ooov(n,o,k,g)
                        hmatel = -h2b_ooov(n,o,k,g)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
                     end if
                     ! (ik)
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,c,j,k/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        g = t4_excits_buff(jdet,4); n = t4_excits_buff(jdet,7); o = t4_excits_buff(jdet,8);
                        ! compute < ijkabc | h2b(ooov) | jkno~abcg~ >
                        !hmatel = -h2b_ooov(n,o,i,g)
                        hmatel = -h2b_ooov(n,o,i,g)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
                     end if
                     ! (jk)
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,c,i,k/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        g = t4_excits_buff(jdet,4); n = t4_excits_buff(jdet,7); o = t4_excits_buff(jdet,8);
                        ! compute < ijkabc | h2b(ooov) | ikno~abcg~ >
                        !hmatel = h2b_ooov(n,o,j,g)
                        hmatel = h2b_ooov(n,o,j,g)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
                     end if
                  end do
                  !$omp end do
                  !$omp end parallel
                  !!!! END OMP PARALLEL SECTION !!!!
                  !!! ABCIK LOOP !!!
                  call sort_pspace(t4_excits_buff, t4_amps_buff, n4aaab, 5, (/1,2,3,5,7/), kdims, kchain, nblock, block_key, block_off)
                  !!!! BEGIN OMP PARALLEL SECTION !!!!
                  !$omp parallel shared(resid,&
                  !$omp t3a_excits,t4_excits_buff,&
                  !$omp t3a_amps,t4_amps_buff,&
                  !$omp nblock,block_key,block_off,kdims,kchain,&
                  !$omp H2B_ooov,&
                  !$omp noa,nua,nob,nub,n3aaa),&
                  !$omp private(hmatel,a,b,c,d,i,j,k,l,e,f,m,n,g,o,idet,jdet,&
                  !$omp idx)
                  !$omp do schedule(static)
                  do idet = 1, n3aaa
                     a = t3a_excits(idet,1); b = t3a_excits(idet,2); c = t3a_excits(idet,3);
                     i = t3a_excits(idet,4); j = t3a_excits(idet,5); k = t3a_excits(idet,6);
                     ! (1)
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,c,i,k/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        g = t4_excits_buff(jdet,4); m = t4_excits_buff(jdet,6); o = t4_excits_buff(jdet,8);
                        ! compute < ijkabc | h2b(ooov) | imko~abcg~ >
                        !hmatel = -h2b_ooov(m,o,j,g)
                        hmatel = -h2b_ooov(m,o,j,g)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
                     end if
                     ! (ij)
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,c,j,k/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        g = t4_excits_buff(jdet,4); m = t4_excits_buff(jdet,6); o = t4_excits_buff(jdet,8);
                        ! compute < ijkabc | h2b(ooov) | jmko~abcg~ >
                        !hmatel = h2b_ooov(m,o,i,g)
                        hmatel = h2b_ooov(m,o,i,g)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
                     end if
                     ! (jk)
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,c,i,j/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        g = t4_excits_buff(jdet,4); m = t4_excits_buff(jdet,6); o = t4_excits_buff(jdet,8);
                        ! compute < ijkabc | h2b(ooov) | imjo~abcg~ >
                        !hmatel = h2b_ooov(m,o,k,g)
                        hmatel = h2b_ooov(m,o,k,g)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
                     end if
                  end do
                  !$omp end do
                  !$omp end parallel
                  !!!! END OMP PARALLEL SECTION !!!!
                  !!! ABCJK LOOP !!!
                  call sort_pspace(t4_excits_buff, t4_amps_buff, n4aaab, 5, (/1,2,3,6,7/), kdims, kchain, nblock, block_key, block_off)
                  !!!! BEGIN OMP PARALLEL SECTION !!!!
                  !$omp parallel shared(resid,&
                  !$omp t3a_excits,t4_excits_buff,&
                  !$omp t3a_amps,t4_amps_buff,&
                  !$omp nblock,block_key,block_off,kdims,kchain,&
                  !$omp H2B_ooov,&
                  !$omp noa,nua,nob,nub,n3aaa),&
                  !$omp private(hmatel,a,b,c,d,i,j,k,l,e,f,m,n,g,o,idet,jdet,&
                  !$omp idx)
                  !$omp do schedule(static)
                  do idet = 1, n3aaa
                     a = t3a_excits(idet,1); b = t3a_excits(idet,2); c = t3a_excits(idet,3);
                     i = t3a_excits(idet,4); j = t3a_excits(idet,5); k = t3a_excits(idet,6);
                     ! (1)
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,c,j,k/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        g = t4_excits_buff(jdet,4); l = t4_excits_buff(jdet,5); o = t4_excits_buff(jdet,8);
                        ! compute < ijkabc | h2b(ooov) | ljko~abcg~ >
                        !hmatel = -h2b_ooov(l,o,i,g)
                        hmatel = -h2b_ooov(l,o,i,g)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
                     end if
                     ! (ij)
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,c,i,k/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        g = t4_excits_buff(jdet,4); l = t4_excits_buff(jdet,5); o = t4_excits_buff(jdet,8);
                        ! compute < ijkabc | h2b(ooov) | liko~abcg~ >
                        !hmatel = h2b_ooov(l,o,j,g)
                        hmatel = h2b_ooov(l,o,j,g)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
                     end if
                     ! (ik)
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,c,i,j/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        g = t4_excits_buff(jdet,4); l = t4_excits_buff(jdet,5); o = t4_excits_buff(jdet,8);
                        ! compute < ijkabc | h2b(ooov) | lijo~abcg~ >
                        !hmatel = -h2b_ooov(l,o,k,g)
                        hmatel = -h2b_ooov(l,o,k,g)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
                     end if
                  end do
                  !$omp end do
                  !$omp end parallel
                  !!!! END OMP PARALLEL SECTION !!!!
                  ! deallocate sorting arrays
                  deallocate(block_key,block_off)
                  ! deallocate t4 buffer arrays
                  deallocate(t4_amps_buff,t4_excits_buff)

                  ! Update t3 vector
                  !$omp parallel shared(resid,t3a_excits,t3a_amps,fA_oo,fA_vv,n3aaa,shift),&
                  !$omp private(idet,a,b,c,i,j,k,denom)
                  !$omp do schedule(static)
                  do idet = 1, n3aaa
                      a = t3a_excits(idet,1); b = t3a_excits(idet,2); c = t3a_excits(idet,3);
                      i = t3a_excits(idet,4); j = t3a_excits(idet,5); k = t3a_excits(idet,6);
                      denom = fA_oo(i,i) + fA_oo(j,j) + fA_oo(k,k) - fA_vv(a,a) - fA_vv(b,b) - fA_vv(c,c)
                      resid(idet) = resid(idet)/(denom - shift)
                      t3a_amps(idet) = t3a_amps(idet) + resid(idet)
                  end do
                  !$omp end do
                  !$omp end parallel

              end subroutine update_t3a_p

              subroutine update_t3b_p(resid,&
                                      t3a_amps, t3a_excits, t3b_amps, t3b_excits,&
                                      t3c_amps, t3c_excits, t2a, t2b,&
                                      H1A_oo, H1A_vv, H1B_oo, H1B_vv,&
                                      H2A_oovv, H2A_vvov, H2A_vooo, H2A_oooo,&
                                      H2A_voov, H2A_vvvv, H2B_oovv, H2B_vvov,&
                                      H2B_vvvo, H2B_vooo, H2B_ovoo, H2B_oooo,&
                                      H2B_voov, H2B_vovo, H2B_ovov, H2B_ovvo,&
                                      H2B_vvvv, H2C_oovv, H2C_voov, fA_oo,&
                                      fA_vv, fB_oo, fB_vv, t4b_amps,&
                                      t4b_excits, t4c_amps, t4c_excits, H1A_ov,&
                                      H1B_ov, H2A_ooov, H2B_ooov, H2B_oovo,&
                                      H2C_ooov, H2A_vovv, H2B_vovv, H2B_ovvv,&
                                      H2C_vovv, shift, n3aaa, n3aab,&
                                      n3abb, noa, nua, nob,&
                                      nub, n4aaab, n4aabb)
                  integer, intent(in) :: n3aaa, n3aab, n3abb, noa, nua, nob, nub, n4aaab, n4aabb
                  integer, intent(in) :: t3a_excits(n3aaa,6), t3c_excits(n3abb,6)
                  real(kind=8), intent(in) :: t3a_amps(n3aaa), t3c_amps(n3abb), t2a(nua,nua,noa,noa),&
                                              t2b(nua,nub,noa,nob), H1A_oo(noa,noa), H1A_vv(nua,nua),&
                                              H1B_oo(nob,nob), H1B_vv(nub,nub), H2A_oovv(noa,noa,nua,nua),&
                                              H2A_vvov(nua,nua,nua,noa), H2A_vooo(noa,nua,noa,noa), H2A_oooo(noa,noa,noa,noa),&
                                              H2A_voov(noa,nua,nua,noa), H2A_vvvv(nua,nua,nua,nua), H2B_oovv(noa,nob,nua,nub),&
                                              H2B_vvov(nub,nua,nub,noa), H2B_vvvo(nua,nua,nub,nob), H2B_vooo(nob,nua,noa,nob),&
                                              H2B_ovoo(noa,nub,noa,nob), H2B_oooo(noa,nob,noa,nob), H2B_voov(nob,nub,nua,noa),&
                                              H2B_vovo(nob,nua,nua,nob), H2B_ovov(noa,nub,nub,noa), H2B_ovvo(noa,nua,nub,nob),&
                                              H2B_vvvv(nub,nua,nub,nua), H2C_oovv(nob,nob,nub,nub), H2C_voov(nob,nub,nub,nob),&
                                              fA_oo(noa,noa), fA_vv(nua,nua), fB_oo(nob,nob),&
                                              fB_vv(nub,nub), shift
                  integer, intent(inout) :: t3b_excits(n3aab,6)
                  !f2py intent(in,out) :: t3b_excits(0:n3aab-1,0:5)
                  real(kind=8), intent(inout) :: t3b_amps(n3aab)
                  !f2py intent(in,out) :: t3b_amps(0:n3aab-1)
                  real(kind=8), intent(out) :: resid(n3aab)
                  real(kind=8), intent(in) :: t4b_amps(n4aaab)
                  integer, intent(in) :: t4b_excits(n4aaab,8)
                  real(kind=8), intent(in) :: t4c_amps(n4aabb)
