                     a = t3b_excits(idet,1); b = t3b_excits(idet,2); c = t3b_excits(idet,3);
                     i = t3b_excits(idet,4); j = t3b_excits(idet,5); k = t3b_excits(idet,6);
                     ! (1)
                     idx = idx_table(a,c,i,k)
                     if (idx/=0) then
                        do jdet = loc_arr(1,idx), loc_arr(2,idx)
                           e = t3_excits_buff(jdet,2); n = t3_excits_buff(jdet,6);
                           ! compute < ijkabc | h2b(voov) | ik~n~ae~c~ >
                           !hmatel = -h2b_voov(b,n,j,e)
                           hmatel = -h2b_voov(n,e,b,j)
                           resid(idet) = resid(idet) + hmatel * t3_amps_buff(jdet)
                        end do
                     end if
                     ! (ab)
                     idx = idx_table(b,c,i,k)
                     if (idx/=0) then
                        do jdet = loc_arr(1,idx), loc_arr(2,idx)
                           e = t3_excits_buff(jdet,2); n = t3_excits_buff(jdet,6);
                           ! compute < ijkabc | h2b(voov) | ik~n~be~c~ >
                           !hmatel = h2b_voov(a,n,j,e)
                           hmatel = h2b_voov(n,e,a,j)
                           resid(idet) = resid(idet) + hmatel * t3_amps_buff(jdet)
                        end do
                     end if
                     ! (ij)
                     idx = idx_table(a,c,j,k)
                     if (idx/=0) then
                        do jdet = loc_arr(1,idx), loc_arr(2,idx)
                           e = t3_excits_buff(jdet,2); n = t3_excits_buff(jdet,6);
                           ! compute < ijkabc | h2b(voov) | jk~n~ae~c~ >
                           !hmatel = h2b_voov(b,n,i,e)
                           hmatel = h2b_voov(n,e,b,i)
                           resid(idet) = resid(idet) + hmatel * t3_amps_buff(jdet)
                        end do
                     end if
                     ! (ab)(ij)
                     idx = idx_table(b,c,j,k)
                     if (idx/=0) then
                        do jdet = loc_arr(1,idx), loc_arr(2,idx)
                           e = t3_excits_buff(jdet,2); n = t3_excits_buff(jdet,6);
                           ! compute < ijkabc | h2b(voov) | jk~n~be~c~ >
                           !hmatel = -h2b_voov(a,n,i,e)
                           hmatel = -h2b_voov(n,e,a,i)
                           resid(idet) = resid(idet) + hmatel * t3_amps_buff(jdet)
                        end do
                     end if
                  end do
                  !$omp end do
                  !$omp end parallel
                  !!!! END OMP PARALLEL SECTION !!!!
                  !!! ABIJ LOOP !!!
                  call get_index_table(idx_table, (/1,nua/), (/1,nub-1/), (/1,noa/), (/1,nob-1/), nua, nub, noa, nob)
                  call sort4(t3_excits_buff, t3_amps_buff, loc_arr, idx_table, (/1,2,4,5/), nua, nub, noa, nob, nloc, n3abb)
                  !!!! BEGIN OMP PARALLEL SECTION !!!!
                  !$omp parallel shared(resid,&
                  !$omp t3b_excits,t3_excits_buff,&
                  !$omp t3b_amps,t3_amps_buff,&
                  !$omp loc_arr,idx_table,&
                  !$omp H2B_voov,&
                  !$omp noa,nua,nob,nub,n3aab),&
                  !$omp private(hmatel,a,b,c,d,i,j,k,l,e,f,m,n,idet,jdet,&
                  !$omp idx)
                  !$omp do schedule(static)
                  do idet = 1, n3aab
                     a = t3b_excits(idet,1); b = t3b_excits(idet,2); c = t3b_excits(idet,3);
                     i = t3b_excits(idet,4); j = t3b_excits(idet,5); k = t3b_excits(idet,6);
                     ! (1)
                     idx = idx_table(a,c,i,k)
                     if (idx/=0) then
                        do jdet = loc_arr(1,idx), loc_arr(2,idx)
                           f = t3_excits_buff(jdet,3); n = t3_excits_buff(jdet,6);
                           ! compute < ijkabc | h2b(voov) | ik~n~ac~f~ >
                           !hmatel = h2b_voov(b,n,j,f)
                           hmatel = h2b_voov(n,f,b,j)
                           resid(idet) = resid(idet) + hmatel * t3_amps_buff(jdet)
                        end do
                     end if
                     ! (ab)
                     idx = idx_table(b,c,i,k)
                     if (idx/=0) then
                        do jdet = loc_arr(1,idx), loc_arr(2,idx)
                           f = t3_excits_buff(jdet,3); n = t3_excits_buff(jdet,6);
                           ! compute < ijkabc | h2b(voov) | ik~n~bc~f~ >
                           !hmatel = -h2b_voov(a,n,j,f)
                           hmatel = -h2b_voov(n,f,a,j)
                           resid(idet) = resid(idet) + hmatel * t3_amps_buff(jdet)
                        end do
                     end if
                     ! (ij)
                     idx = idx_table(a,c,j,k)
                     if (idx/=0) then
                        do jdet = loc_arr(1,idx), loc_arr(2,idx)
                           f = t3_excits_buff(jdet,3); n = t3_excits_buff(jdet,6);
                           ! compute < ijkabc | h2b(voov) | jk~n~ac~f~ >
                           !hmatel = -h2b_voov(b,n,i,f)
                           hmatel = -h2b_voov(n,f,b,i)
                           resid(idet) = resid(idet) + hmatel * t3_amps_buff(jdet)
                        end do
                     end if
                     ! (ab)(ij)
                     idx = idx_table(b,c,j,k)
                     if (idx/=0) then
                        do jdet = loc_arr(1,idx), loc_arr(2,idx)
                           f = t3_excits_buff(jdet,3); n = t3_excits_buff(jdet,6);
                           ! compute < ijkabc | h2b(voov) | jk~n~bc~f~ >
                           !hmatel = h2b_voov(a,n,i,f)
                           hmatel = h2b_voov(n,f,a,i)
                           resid(idet) = resid(idet) + hmatel * t3_amps_buff(jdet)
                        end do
                     end if
                  end do
                  !$omp end do
                  !$omp end parallel
                  !!!! END OMP PARALLEL SECTION !!!!
                  ! deallocate sorting arrays
                  deallocate(loc_arr,idx_table)
                  ! deallocate t3 buffer arrays
                  deallocate(t3_amps_buff,t3_excits_buff)

                  !
                  ! Moment contributions
                  !
                  !$omp parallel shared(resid,t3b_excits,t2a,I2B_vvvo,n3aab),&
                  !$omp private(idet,a,b,c,i,j,k,e)
                  !$omp do schedule(static)
                  do idet = 1, n3aab
                      a = t3b_excits(idet,1); b = t3b_excits(idet,2); c = t3b_excits(idet,3);
                      i = t3b_excits(idet,4); j = t3b_excits(idet,5); k = t3b_excits(idet,6);
                      do e = 1, nua
                          ! A(ab) I2B(bcek) * t2a(aeij)
                          resid(idet) = resid(idet) + I2B_vvvo(e,b,c,k) * t2a(e,a,j,i)
                          resid(idet) = resid(idet) - I2B_vvvo(e,a,c,k) * t2a(e,b,j,i)
                      end do
                  end do
                  !$omp end do
                  !$omp end parallel
                  !$omp parallel shared(resid,t3b_excits,t2b,I2A_vvov,n3aab),&
                  !$omp private(idet,a,b,c,i,j,k,e)
                  !$omp do schedule(static)
                  do idet = 1, n3aab
                      a = t3b_excits(idet,1); b = t3b_excits(idet,2); c = t3b_excits(idet,3);
                      i = t3b_excits(idet,4); j = t3b_excits(idet,5); k = t3b_excits(idet,6);
                      do e = 1, nua
                          ! A(ij) I2A(abie) * t2b(ecjk)
                          resid(idet) = resid(idet) + I2A_vvov(e,a,b,i) * t2b(e,c,j,k)
                          resid(idet) = resid(idet) - I2A_vvov(e,a,b,j) * t2b(e,c,i,k)
                      end do
                  end do
                  !$omp end do
                  !$omp end parallel
                  allocate(xbuf(nub,nua,nob,noa))
                  do i = 1,noa
                     do j = 1,nob
                        do a = 1,nua
                           do b = 1,nub
                              xbuf(b,a,j,i) = t2b(a,b,i,j)
                           end do
                        end do
                     end do
                  end do
                  !$omp parallel shared(resid,t3b_excits,xbuf,I2B_vvov,n3aab),&
                  !$omp private(idet,a,b,c,i,j,k,e)
                  !$omp do schedule(static)
                  do idet = 1, n3aab
                      a = t3b_excits(idet,1); b = t3b_excits(idet,2); c = t3b_excits(idet,3);
                      i = t3b_excits(idet,4); j = t3b_excits(idet,5); k = t3b_excits(idet,6);
                      do e = 1, nub
                          ! A(ij)A(ab) I2b(acie) * t2b(bejk)
                          resid(idet) = resid(idet) + I2B_vvov(e,a,c,i) * xbuf(e,b,k,j)
                          resid(idet) = resid(idet) - I2B_vvov(e,a,c,j) * xbuf(e,b,k,i)
                          resid(idet) = resid(idet) - I2B_vvov(e,b,c,i) * xbuf(e,a,k,j)
                          resid(idet) = resid(idet) + I2B_vvov(e,b,c,j) * xbuf(e,a,k,i)
                      end do
                  end do
                  !$omp end do
                  !$omp end parallel
                  deallocate(xbuf)
                  allocate(xbuf(noa,noa,nua,nua))
                  do a = 1,nua
                     do b = 1,nua
                        do i = 1,noa
                           do j = 1,noa
                              xbuf(j,i,b,a) = t2a(b,a,j,i)
                           end do
                        end do
                     end do
                  end do
                  !$omp parallel shared(resid,t3b_excits,xbuf,I2B_ovoo,n3aab),&
                  !$omp private(idet,a,b,c,i,j,k,m)
                  !$omp do schedule(static)
                  do idet = 1, n3aab
                      a = t3b_excits(idet,1); b = t3b_excits(idet,2); c = t3b_excits(idet,3);
                      i = t3b_excits(idet,4); j = t3b_excits(idet,5); k = t3b_excits(idet,6);
                      do m = 1, noa
                          ! -A(ij) h2b(mcjk) * t2a(abim)
                          resid(idet) = resid(idet) - I2B_ovoo(m,c,j,k) * xbuf(m,i,b,a)
                          resid(idet) = resid(idet) + I2B_ovoo(m,c,i,k) * xbuf(m,j,b,a)
                      end do
                  end do
                  !$omp end do
                  !$omp end parallel
                  deallocate(xbuf)
                  allocate(xbuf(noa,nob,nua,nub))
                  do b = 1,nub
                     do a = 1,nua
                        do j = 1,nob
                           do i = 1,noa
                              xbuf(i,j,a,b) = t2b(a,b,i,j)
                           end do
                        end do
                     end do
                  end do
                  !$omp parallel shared(resid,t3b_excits,xbuf,I2A_vooo,n3aab),&
                  !$omp private(idet,a,b,c,i,j,k,m)
                  !$omp do schedule(static)
                  do idet = 1, n3aab
                      a = t3b_excits(idet,1); b = t3b_excits(idet,2); c = t3b_excits(idet,3);
                      i = t3b_excits(idet,4); j = t3b_excits(idet,5); k = t3b_excits(idet,6);
                      do m = 1, noa
                          ! -A(ab) h2a(amij) * t2b(bcmk)
                          resid(idet) = resid(idet) - I2A_vooo(m,a,i,j) * xbuf(m,k,b,c)
                          resid(idet) = resid(idet) + I2A_vooo(m,b,i,j) * xbuf(m,k,a,c)
                      end do
                  end do
                  !$omp end do
                  !$omp end parallel
                  deallocate(xbuf)
                  allocate(xbuf(nob,noa,nub,nua))
                  do a = 1,nua
                     do b = 1,nub
                        do i = 1,noa
                           do j = 1,nob
                              xbuf(j,i,b,a) = t2b(a,b,i,j)
                           end do
                        end do
                     end do
                  end do
                  !$omp parallel shared(resid,t3b_excits,xbuf,I2B_vooo,n3aab),&
                  !$omp private(idet,a,b,c,i,j,k,m)
                  !$omp do schedule(static)
                  do idet = 1, n3aab
                      a = t3b_excits(idet,1); b = t3b_excits(idet,2); c = t3b_excits(idet,3);
                      i = t3b_excits(idet,4); j = t3b_excits(idet,5); k = t3b_excits(idet,6);
                      do m = 1, nob
                          ! -A(ij)A(ab) h2b(amik) * t2b(bcjm)
                          resid(idet) = resid(idet) - I2B_vooo(m,a,i,k) * xbuf(m,j,c,b)
                          resid(idet) = resid(idet) + I2B_vooo(m,b,i,k) * xbuf(m,j,c,a)
                          resid(idet) = resid(idet) + I2B_vooo(m,a,j,k) * xbuf(m,i,c,b)
                          resid(idet) = resid(idet) - I2B_vooo(m,b,j,k) * xbuf(m,i,c,a)
                      end do
                  end do
                  !$omp end do
                  !$omp end parallel
                  deallocate(xbuf)

                  !!!! +0.25 * H.a.ov(me) * T.aaab(abecijmk) -> abcijk
                  ! allocate and copy over t4b arrays
                  allocate(t4_amps_buff(n4aaab),t4_excits_buff(n4aaab,8))
                  t4_amps_buff(:) = t4b_amps(:)
                  t4_excits_buff(:,:) = t4b_excits(:,:)
                  ! allocate sorting arrays (can be reused for each permutation)
                  kdims(1:6) = (/nua,nua,nub,noa,noa,nob/)
                  kchain(1:6) = (/.false.,.true.,.false.,.false.,.true.,.false./)
                  !!! ABDIJL LOOP !!!
                  call sort_pspace(t4_excits_buff, t4_amps_buff, n4aaab, 6, (/1,2,4,5,6,8/), kdims, kchain, nblock, block_key, block_off)
                  !!!! BEGIN OMP PARALLEL SECTION !!!!
                  !$omp parallel shared(resid,&
                  !$omp t3b_excits,t4_excits_buff,&
                  !$omp t3b_amps,t4_amps_buff,&
                  !$omp nblock,block_key,block_off,kdims,kchain,&
                  !$omp H1A_ov,&
                  !$omp noa,nua,nob,nub,n3aab),&
                  !$omp private(hmatel,a,b,c,d,i,j,k,l,e,f,m,n,idet,jdet,&
                  !$omp idx)
                  !$omp do schedule(static)
                  do idet = 1, n3aab
                     a = t3b_excits(idet,1); b = t3b_excits(idet,2); c = t3b_excits(idet,3);
                     i = t3b_excits(idet,4); j = t3b_excits(idet,5); k = t3b_excits(idet,6);
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,c,i,j,k/), 6, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        f = t4_excits_buff(jdet,3); n = t4_excits_buff(jdet,7);
                        ! compute < ijkabc | h1a(ov) | ijnk~abfc~ >
                        !hmatel = h1a_ov(n,f)
                        hmatel = h1a_ov(n,f)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
                     end if
                  end do
                  !$omp end do
                  !$omp end parallel
                  !!!! END OMP PARALLEL SECTION !!!!
                  !!! ACDIJL LOOP !!!
                  call sort_pspace(t4_excits_buff, t4_amps_buff, n4aaab, 6, (/1,3,4,5,6,8/), kdims, kchain, nblock, block_key, block_off)
                  !!!! BEGIN OMP PARALLEL SECTION !!!!
                  !$omp parallel shared(resid,&
                  !$omp t3b_excits,t4_excits_buff,&
                  !$omp t3b_amps,t4_amps_buff,&
                  !$omp nblock,block_key,block_off,kdims,kchain,&
                  !$omp H1A_ov,&
                  !$omp noa,nua,nob,nub,n3aab),&
                  !$omp private(hmatel,a,b,c,d,i,j,k,l,e,f,m,n,idet,jdet,&
                  !$omp idx)
                  !$omp do schedule(static)
                  do idet = 1, n3aab
                     a = t3b_excits(idet,1); b = t3b_excits(idet,2); c = t3b_excits(idet,3);
                     i = t3b_excits(idet,4); j = t3b_excits(idet,5); k = t3b_excits(idet,6);
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,c,i,j,k/), 6, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        e = t4_excits_buff(jdet,2); n = t4_excits_buff(jdet,7);
                        ! compute < ijkabc | h1a(ov) | ijnk~aebc~ >
                        !hmatel = -h1a_ov(n,e)
                        hmatel = -h1a_ov(n,e)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
                     end if
                  end do
                  !$omp end do
                  !$omp end parallel
                  !!!! END OMP PARALLEL SECTION !!!!
                  !!! BCDIJL LOOP !!!
                  call sort_pspace(t4_excits_buff, t4_amps_buff, n4aaab, 6, (/2,3,4,5,6,8/), kdims, kchain, nblock, block_key, block_off)
                  !!!! BEGIN OMP PARALLEL SECTION !!!!
                  !$omp parallel shared(resid,&
                  !$omp t3b_excits,t4_excits_buff,&
                  !$omp t3b_amps,t4_amps_buff,&
                  !$omp nblock,block_key,block_off,kdims,kchain,&
                  !$omp H1A_ov,&
                  !$omp noa,nua,nob,nub,n3aab),&
                  !$omp private(hmatel,a,b,c,d,i,j,k,l,e,f,m,n,idet,jdet,&
                  !$omp idx)
                  !$omp do schedule(static)
                  do idet = 1, n3aab
                     a = t3b_excits(idet,1); b = t3b_excits(idet,2); c = t3b_excits(idet,3);
                     i = t3b_excits(idet,4); j = t3b_excits(idet,5); k = t3b_excits(idet,6);
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,c,i,j,k/), 6, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        d = t4_excits_buff(jdet,1); n = t4_excits_buff(jdet,7);
                        ! compute < ijkabc | h1a(ov) | ijnk~dabc~ >
                        !hmatel = h1a_ov(n,d)
                        hmatel = h1a_ov(n,d)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
                     end if
                  end do
                  !$omp end do
                  !$omp end parallel
                  !!!! END OMP PARALLEL SECTION !!!!
                  !!! ABDIKL LOOP !!!
                  call sort_pspace(t4_excits_buff, t4_amps_buff, n4aaab, 6, (/1,2,4,5,7,8/), kdims, kchain, nblock, block_key, block_off)
                  !!!! BEGIN OMP PARALLEL SECTION !!!!
                  !$omp parallel shared(resid,&
                  !$omp t3b_excits,t4_excits_buff,&
                  !$omp t3b_amps,t4_amps_buff,&
                  !$omp nblock,block_key,block_off,kdims,kchain,&
                  !$omp H1A_ov,&
                  !$omp noa,nua,nob,nub,n3aab),&
                  !$omp private(hmatel,a,b,c,d,i,j,k,l,e,f,m,n,idet,jdet,&
                  !$omp idx)
                  !$omp do schedule(static)
                  do idet = 1, n3aab
                     a = t3b_excits(idet,1); b = t3b_excits(idet,2); c = t3b_excits(idet,3);
                     i = t3b_excits(idet,4); j = t3b_excits(idet,5); k = t3b_excits(idet,6);
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,c,i,j,k/), 6, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        f = t4_excits_buff(jdet,3); m = t4_excits_buff(jdet,6);
                        ! compute < ijkabc | h1a(ov) | imjk~abfc~ >
                        !hmatel = -h1a_ov(m,f)
                        hmatel = -h1a_ov(m,f)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
                     end if
                  end do
                  !$omp end do
                  !$omp end parallel
                  !!!! END OMP PARALLEL SECTION !!!!
                  !!! ACDIKL LOOP !!!
                  call sort_pspace(t4_excits_buff, t4_amps_buff, n4aaab, 6, (/1,3,4,5,7,8/), kdims, kchain, nblock, block_key, block_off)
                  !!!! BEGIN OMP PARALLEL SECTION !!!!
                  !$omp parallel shared(resid,&
                  !$omp t3b_excits,t4_excits_buff,&
                  !$omp t3b_amps,t4_amps_buff,&
                  !$omp nblock,block_key,block_off,kdims,kchain,&
                  !$omp H1A_ov,&
                  !$omp noa,nua,nob,nub,n3aab),&
                  !$omp private(hmatel,a,b,c,d,i,j,k,l,e,f,m,n,idet,jdet,&
                  !$omp idx)
                  !$omp do schedule(static)
                  do idet = 1, n3aab
                     a = t3b_excits(idet,1); b = t3b_excits(idet,2); c = t3b_excits(idet,3);
                     i = t3b_excits(idet,4); j = t3b_excits(idet,5); k = t3b_excits(idet,6);
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,c,i,j,k/), 6, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        e = t4_excits_buff(jdet,2); m = t4_excits_buff(jdet,6);
                        ! compute < ijkabc | h1a(ov) | imjk~aebc~ >
                        !hmatel = h1a_ov(m,e)
                        hmatel = h1a_ov(m,e)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
                     end if
                  end do
                  !$omp end do
                  !$omp end parallel
