                  real(kind=8), intent(in) :: H1A_vv(nua,nua)
                  real(kind=8), intent(in) :: H2A_oooo(noa,noa,noa,noa)
                  real(kind=8), intent(in) :: H2A_ooov(noa,noa,noa,nua)
                  real(kind=8), intent(in) :: H2A_vooo(nua,noa,noa,noa)
                  real(kind=8), intent(in) :: H2A_voov(nua,noa,noa,nua)
                  real(kind=8), intent(in) :: H2A_vovv(nua,noa,nua,nua)
                  real(kind=8), intent(in) :: H2A_vvov(nua,nua,noa,nua)
                  real(kind=8), intent(in) :: H2A_vvvv(nua,nua,nua,nua)
                  real(kind=8), intent(in) :: H2B_ooov(noa,nob,noa,nub)
                  real(kind=8), intent(in) :: H2B_voov(nua,nob,noa,nub)
                  real(kind=8), intent(in) :: H2B_vovv(nua,nob,nua,nub)
                  real(kind=8), intent(in) :: H2A_oovv(noa,noa,nua,nua)
                  real(kind=8), intent(in) :: H2B_oovv(noa,nob,nua,nub)
                  real(kind=8), intent(in) :: H2C_oovv(nob,nob,nub,nub)
                  real(kind=8), intent(in) :: fA_oo(noa,noa), fA_vv(nua,nua), fB_oo(nob,nob), fB_vv(nub,nub), shift

                  integer, intent(inout) :: t4a_excits(n4aaaa,8)
                  !f2py intent(in,out) :: t4a_excits(0:n4aaaa-1,0:7)
                  real(kind=8), intent(inout) :: t4a_amps(n4aaaa)
                  !f2py intent(in,out) :: t4a_amps(0:n4aaaa-1)
                  real(kind=8), intent(out) :: resid(n4aaaa)

                  real(kind=8), allocatable :: h2a_vvov_3012(:,:,:,:)
                  real(kind=8), allocatable :: h2a_vooo_1023(:,:,:,:)
                  real(kind=8), allocatable :: h2a_vvvv_2301(:,:,:,:)
                  real(kind=8), allocatable :: h1a_vv_10(:,:)
                  real(kind=8), allocatable :: h2a_voov_1302(:,:,:,:)
                  real(kind=8), allocatable :: h2b_voov_1302(:,:,:,:)
                  real(kind=8), allocatable :: h2a_vovv_2301(:,:,:,:)
                  real(kind=8), allocatable :: h2a_ooov_1302(:,:,:,:)
                  real(kind=8), allocatable :: h2a_vovv_1302(:,:,:,:)
                  real(kind=8), allocatable :: h2a_oovv_1302(:,:,:,:)
                  real(kind=8), allocatable :: h2b_oovv_0213(:,:,:,:)
                  real(kind=8), allocatable :: h2b_ooov_1302(:,:,:,:)
                  real(kind=8), allocatable :: h2b_vovv_1302(:,:,:,:)
                  real(kind=8), allocatable :: h2c_oovv_1302(:,:,:,:)
                  real(kind=8), allocatable :: h2a_voov_1023(:,:,:,:)
                  real(kind=8), allocatable :: h2a_oooo_1023(:,:,:,:)
                  real(kind=8), allocatable :: h2a_oovv_1023(:,:,:,:)
                  real(kind=8), allocatable :: h2a_vvvv_3012(:,:,:,:)
                  real(kind=8), allocatable :: h2a_oovv_3012(:,:,:,:)
                  real(kind=8), allocatable :: h2b_oovv_2013(:,:,:,:)
                  integer :: idet, p1, p2, p3, p4, a, b, c, d, i, j, k, l
                  real(kind=8) :: denom

                  ! integrals in the layouts of the sparse kernels (summed or block indices first)
                  allocate(h2a_vvov_3012(nua,nua,nua,noa))
                  do p4 = 1, noa
                     do p3 = 1, nua
                        do p2 = 1, nua
                           do p1 = 1, nua
                              h2a_vvov_3012(p1,p2,p3,p4) = H2A_vvov(p2,p3,p4,p1)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2a_vooo_1023(noa,nua,noa,noa))
                  do p4 = 1, noa
                     do p3 = 1, noa
                        do p2 = 1, nua
                           do p1 = 1, noa
                              h2a_vooo_1023(p1,p2,p3,p4) = H2A_vooo(p2,p1,p3,p4)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2a_vvvv_2301(nua,nua,nua,nua))
                  do p4 = 1, nua
                     do p3 = 1, nua
                        do p2 = 1, nua
                           do p1 = 1, nua
                              h2a_vvvv_2301(p1,p2,p3,p4) = H2A_vvvv(p3,p4,p1,p2)
                           end do
                        end do
                     end do
                  end do
                  allocate(h1a_vv_10(nua,nua))
                  do p2 = 1, nua
                     do p1 = 1, nua
                        h1a_vv_10(p1,p2) = H1A_vv(p2,p1)
                     end do
                  end do
                  allocate(h2a_voov_1302(noa,nua,nua,noa))
                  do p4 = 1, noa
                     do p3 = 1, nua
                        do p2 = 1, nua
                           do p1 = 1, noa
                              h2a_voov_1302(p1,p2,p3,p4) = H2A_voov(p3,p1,p4,p2)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2b_voov_1302(nob,nub,nua,noa))
                  do p4 = 1, noa
                     do p3 = 1, nua
                        do p2 = 1, nub
                           do p1 = 1, nob
                              h2b_voov_1302(p1,p2,p3,p4) = H2B_voov(p3,p1,p4,p2)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2a_vovv_2301(nua,nua,nua,noa))
                  do p4 = 1, noa
                     do p3 = 1, nua
                        do p2 = 1, nua
                           do p1 = 1, nua
                              h2a_vovv_2301(p1,p2,p3,p4) = H2A_vovv(p3,p4,p1,p2)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2a_ooov_1302(noa,nua,noa,noa))
                  do p4 = 1, noa
                     do p3 = 1, noa
                        do p2 = 1, nua
                           do p1 = 1, noa
                              h2a_ooov_1302(p1,p2,p3,p4) = H2A_ooov(p3,p1,p4,p2)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2a_vovv_1302(noa,nua,nua,nua))
                  do p4 = 1, nua
                     do p3 = 1, nua
                        do p2 = 1, nua
                           do p1 = 1, noa
                              h2a_vovv_1302(p1,p2,p3,p4) = H2A_vovv(p3,p1,p4,p2)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2a_oovv_1302(noa,nua,noa,nua))
                  do p4 = 1, nua
                     do p3 = 1, noa
                        do p2 = 1, nua
                           do p1 = 1, noa
                              h2a_oovv_1302(p1,p2,p3,p4) = H2A_oovv(p3,p1,p4,p2)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2b_oovv_0213(noa,nua,nob,nub))
                  do p4 = 1, nub
                     do p3 = 1, nob
                        do p2 = 1, nua
                           do p1 = 1, noa
                              h2b_oovv_0213(p1,p2,p3,p4) = H2B_oovv(p1,p3,p2,p4)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2b_ooov_1302(nob,nub,noa,noa))
                  do p4 = 1, noa
                     do p3 = 1, noa
                        do p2 = 1, nub
                           do p1 = 1, nob
                              h2b_ooov_1302(p1,p2,p3,p4) = H2B_ooov(p3,p1,p4,p2)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2b_vovv_1302(nob,nub,nua,nua))
                  do p4 = 1, nua
                     do p3 = 1, nua
                        do p2 = 1, nub
                           do p1 = 1, nob
                              h2b_vovv_1302(p1,p2,p3,p4) = H2B_vovv(p3,p1,p4,p2)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2c_oovv_1302(nob,nub,nob,nub))
                  do p4 = 1, nub
                     do p3 = 1, nob
                        do p2 = 1, nub
                           do p1 = 1, nob
                              h2c_oovv_1302(p1,p2,p3,p4) = H2C_oovv(p3,p1,p4,p2)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2a_voov_1023(noa,nua,noa,nua))
                  do p4 = 1, nua
                     do p3 = 1, noa
                        do p2 = 1, nua
                           do p1 = 1, noa
                              h2a_voov_1023(p1,p2,p3,p4) = H2A_voov(p2,p1,p3,p4)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2a_oooo_1023(noa,noa,noa,noa))
                  do p4 = 1, noa
                     do p3 = 1, noa
                        do p2 = 1, noa
                           do p1 = 1, noa
                              h2a_oooo_1023(p1,p2,p3,p4) = H2A_oooo(p2,p1,p3,p4)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2a_oovv_1023(noa,noa,nua,nua))
                  do p4 = 1, nua
                     do p3 = 1, nua
                        do p2 = 1, noa
                           do p1 = 1, noa
                              h2a_oovv_1023(p1,p2,p3,p4) = H2A_oovv(p2,p1,p3,p4)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2a_vvvv_3012(nua,nua,nua,nua))
                  do p4 = 1, nua
                     do p3 = 1, nua
                        do p2 = 1, nua
                           do p1 = 1, nua
                              h2a_vvvv_3012(p1,p2,p3,p4) = H2A_vvvv(p2,p3,p4,p1)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2a_oovv_3012(nua,noa,noa,nua))
                  do p4 = 1, nua
                     do p3 = 1, noa
                        do p2 = 1, noa
                           do p1 = 1, nua
                              h2a_oovv_3012(p1,p2,p3,p4) = H2A_oovv(p2,p3,p4,p1)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2b_oovv_2013(nua,noa,nob,nub))
                  do p4 = 1, nub
                     do p3 = 1, nob
                        do p2 = 1, noa
                           do p1 = 1, nua
                              h2b_oovv_2013(p1,p2,p3,p4) = H2B_oovv(p2,p3,p1,p4)
                           end do
                        end do
                     end do
                  end do

                  ! (H(2) * T3 + H(2) * T4)_C linear terms
                  call t4a_p_lin(resid, t4a_amps, t4a_excits, t3a_amps, t3a_excits, t4b_amps,&
                                 t4b_excits, h2a_vvov_3012, h2a_vooo_1023, H2A_oooo, H1A_oo, h2a_vvvv_2301,&
                                 h1a_vv_10, h2a_voov_1302, h2b_voov_1302, n4aaaa, n3aaa, n4aaab,&
                                 noa, nua, nob, nub)
                  ! (I(T2, T3) * T3)_C terms
                  call t4a_p_b3(resid, t4a_amps, t4a_excits, t3a_amps, t3a_excits, t3b_amps,&
                                t3b_excits, t2a, H2A_ooov, H2A_oovv, h2a_vovv_2301, h2a_ooov_1302,&
                                h2a_vovv_1302, h2a_oovv_1302, h2b_oovv_0213, h2b_ooov_1302, h2b_vovv_1302, h2c_oovv_1302,&
                                n4aaaa, n3aaa, n3aab, noa, nua, nob,&
                                nub)
                  ! (I(T2, T4) * T2)_C and (H * T2 * T2)_C terms
                  call t4a_p_b2(resid, t4a_amps, t4a_excits, t4b_amps, t4b_excits, t2a,&
                                h2a_voov_1023, h2a_oooo_1023, h2a_oovv_1023, H2B_oovv, h2a_vvvv_3012, h2a_oovv_3012,&
                                h2b_oovv_2013, n4aaaa, n4aaab, noa, nua, nob,&
                                nub)
                  deallocate(h2a_vvov_3012)
                  deallocate(h2a_vooo_1023)
                  deallocate(h2a_vvvv_2301)
                  deallocate(h1a_vv_10)
                  deallocate(h2a_voov_1302)
                  deallocate(h2b_voov_1302)
                  deallocate(h2a_vovv_2301)
                  deallocate(h2a_ooov_1302)
                  deallocate(h2a_vovv_1302)
                  deallocate(h2a_oovv_1302)
                  deallocate(h2b_oovv_0213)
                  deallocate(h2b_ooov_1302)
                  deallocate(h2b_vovv_1302)
                  deallocate(h2c_oovv_1302)
                  deallocate(h2a_voov_1023)
                  deallocate(h2a_oooo_1023)
                  deallocate(h2a_oovv_1023)
                  deallocate(h2a_vvvv_3012)
                  deallocate(h2a_oovv_3012)
                  deallocate(h2b_oovv_2013)

                  ! Update t4 vector
                  !$omp parallel shared(resid,t4a_excits,t4a_amps,fA_oo,fA_vv,fB_oo,fB_vv,n4aaaa,shift),&
                  !$omp private(idet,a,b,c,d,i,j,k,l,denom)
                  !$omp do schedule(static)
                  do idet = 1, n4aaaa
                      a = t4a_excits(idet,1); b = t4a_excits(idet,2); c = t4a_excits(idet,3); d = t4a_excits(idet,4);
                      i = t4a_excits(idet,5); j = t4a_excits(idet,6); k = t4a_excits(idet,7); l = t4a_excits(idet,8);
                      denom = fA_oo(i,i) + fA_oo(j,j) + fA_oo(k,k) + fA_oo(l,l) - fA_vv(a,a) - fA_vv(b,b) - fA_vv(c,c) - fA_vv(d,d)
                      resid(idet) = resid(idet)/(denom - shift)
                      t4a_amps(idet) = t4a_amps(idet) + resid(idet)
                  end do
                  !$omp end do
                  !$omp end parallel

              end subroutine update_t4a_p

              subroutine t4a_p_lin(resid,&
                                      t4a_amps, t4a_excits, t3a_amps, t3a_excits,&
                                      t4b_amps, t4b_excits, H2A_vvov, H2A_vooo,&
                                      H2A_oooo, H1A_oo, H2A_vvvv, H1A_vv,&
                                      H2A_voov, H2B_voov, n4aaaa, n3aaa,&
                                      n4aaab, noa, nua, nob,&
                                      nub)
                  integer, intent(in) :: n4aaaa, n3aaa, n4aaab, noa, nua, nob, nub
                  real(kind=8), intent(out) :: resid(n4aaaa)
                  real(kind=8), intent(inout) :: t4a_amps(n4aaaa)
                  !f2py intent(in,out) :: t4a_amps(0:n4aaaa-1)
                  integer, intent(inout) :: t4a_excits(n4aaaa,8)
                  !f2py intent(in,out) :: t4a_excits(0:n4aaaa-1,0:8-1)
                  real(kind=8), intent(in) :: t3a_amps(n3aaa)
                  integer, intent(in) :: t3a_excits(n3aaa,6)
                  real(kind=8), intent(in) :: t4b_amps(n4aaab)
                  integer, intent(in) :: t4b_excits(n4aaab,8)
                  real(kind=8), intent(in) :: H2A_vvov(nua,nua,nua,noa)
                  real(kind=8), intent(in) :: H2A_vooo(noa,nua,noa,noa)
                  real(kind=8), intent(in) :: H2A_oooo(noa,noa,noa,noa)
                  real(kind=8), intent(in) :: H1A_oo(noa,noa)
                  real(kind=8), intent(in) :: H2A_vvvv(nua,nua,nua,nua)
                  real(kind=8), intent(in) :: H1A_vv(nua,nua)
                  real(kind=8), intent(in) :: H2A_voov(noa,nua,nua,noa)
                  real(kind=8), intent(in) :: H2B_voov(nob,nub,nua,noa)
                  integer, allocatable :: idx_table(:,:,:,:), loc_arr(:,:), block_off(:)
                  integer(kind=8), allocatable :: block_key(:)
                  integer :: kdims(6), nblock
                  logical :: kchain(6)
                  real(kind=8), allocatable :: t3_amps_buff(:), t4_amps_buff(:)
                  integer, allocatable :: t3_excits_buff(:,:), t4_excits_buff(:,:)
                  real(kind=8) :: hmatel, hmatel1, hmatel2, hmatel3, hmatel4
                  integer :: a, b, c, d, e, f, g, h, i, j, k, l, m, n, o, p, idet, jdet, idx, nloc
                  resid = 0.0d0

                  !!!! +0.0416667 * H.aa.vvov(cdke) * T.aaa(abeijl) -> abcdijkl
                  ! allocate and copy over t3a arrays
                  allocate(t3_amps_buff(n3aaa),t3_excits_buff(n3aaa,6))
                  t3_amps_buff(:) = t3a_amps(:)
                  t3_excits_buff(:,:) = t3a_excits(:,:)
                  ! allocate sorting arrays (can be reused for each permutation)
                  kdims(1:5) = (/nua,nua,noa,noa,noa/)
                  kchain(1:5) = (/.false.,.true.,.false.,.true.,.true./)
                  !!! ABIJK LOOP !!!
                  call sort_pspace(t3_excits_buff, t3_amps_buff, n3aaa, 5, (/1,2,4,5,6/), kdims, kchain, nblock, block_key, block_off)
                  !!!! BEGIN OMP PARALLEL SECTION !!!!
                  !$omp parallel shared(resid,&
                  !$omp t4a_excits,t3_excits_buff,&
                  !$omp t4a_amps,t3_amps_buff,&
                  !$omp nblock,block_key,block_off,kdims,kchain,&
                  !$omp H2A_vvov,&
                  !$omp noa,nua,n4aaaa),&
                  !$omp private(hmatel,a,b,c,d,i,j,k,l,e,f,m,n,g,idet,jdet,&
                  !$omp idx)
                  !$omp do schedule(static)
                  do idet = 1, n4aaaa
                     a = t4a_excits(idet,1); b = t4a_excits(idet,2); c = t4a_excits(idet,3); d = t4a_excits(idet,4);
                     i = t4a_excits(idet,5); j = t4a_excits(idet,6); k = t4a_excits(idet,7); l = t4a_excits(idet,8);
                     ! (1)
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,i,j,l/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        g = t3_excits_buff(jdet,3);
                        ! compute < ijklabcd | h2a(vvov) | ijlabg >
                        !hmatel = h2a_vvov(c,d,k,g)
                        hmatel = h2a_vvov(g,c,d,k)
                        resid(idet) = resid(idet) + hmatel * t3_amps_buff(jdet)
                     end do
                     end if
                     ! (ac)
                     idx = pspace_find(block_key, nblock, pspace_key((/b,c,i,j,l/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        g = t3_excits_buff(jdet,3);
                        ! compute < ijklabcd | h2a(vvov) | ijlbcg >
                        !hmatel = h2a_vvov(a,d,k,g)
                        hmatel = h2a_vvov(g,a,d,k)
                        resid(idet) = resid(idet) + hmatel * t3_amps_buff(jdet)
                     end do
                     end if
                     ! (ac)(bd)
                     idx = pspace_find(block_key, nblock, pspace_key((/c,d,i,j,l/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        g = t3_excits_buff(jdet,3);
                        ! compute < ijklabcd | h2a(vvov) | ijlcdg >
                        !hmatel = h2a_vvov(a,b,k,g)
                        hmatel = h2a_vvov(g,a,b,k)
                        resid(idet) = resid(idet) + hmatel * t3_amps_buff(jdet)
                     end do
                     end if
                     ! (ad)
                     idx = pspace_find(block_key, nblock, pspace_key((/b,d,i,j,l/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        g = t3_excits_buff(jdet,3);
                        ! compute < ijklabcd | h2a(vvov) | ijlbdg >
                        !hmatel = -h2a_vvov(a,c,k,g)
                        hmatel = -h2a_vvov(g,a,c,k)
                        resid(idet) = resid(idet) + hmatel * t3_amps_buff(jdet)
                     end do
                     end if
                     ! (bc)
                     idx = pspace_find(block_key, nblock, pspace_key((/a,c,i,j,l/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        g = t3_excits_buff(jdet,3);
                        ! compute < ijklabcd | h2a(vvov) | ijlacg >
                        !hmatel = -h2a_vvov(b,d,k,g)
                        hmatel = -h2a_vvov(g,b,d,k)
                        resid(idet) = resid(idet) + hmatel * t3_amps_buff(jdet)
                     end do
                     end if
                     ! (bd)
                     idx = pspace_find(block_key, nblock, pspace_key((/a,d,i,j,l/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        g = t3_excits_buff(jdet,3);
                        ! compute < ijklabcd | h2a(vvov) | ijladg >
                        !hmatel = h2a_vvov(b,c,k,g)
                        hmatel = h2a_vvov(g,b,c,k)
                        resid(idet) = resid(idet) + hmatel * t3_amps_buff(jdet)
                     end do
                     end if
                     ! (ik)
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,j,k,l/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        g = t3_excits_buff(jdet,3);
                        ! compute < ijklabcd | h2a(vvov) | jklabg >
                        !hmatel = h2a_vvov(c,d,i,g)
