                        resid(idet) = resid(idet) - 1d0 * val
                     end do
                  end do
                  !$omp end do
                  deallocate(IX)
                  !$omp end parallel
                  ! +0.0625 * I3B_vvooov(cdxkly) * taab(abyijx), q = (b,d,k,l), sign -1
                  !$omp parallel default(shared) private(IX,val,a,b,c,d,i,j,k,l,x,y,u,v,w,z,r,s,t,g,h,idet,jdet,kdx,idx)
                  allocate(IX(nob,nub))
                  !$omp do schedule(dynamic)
                  do kdx = 1, nloc
                     if (loc_arr(2,kdx) < loc_arr(1,kdx)) cycle
                     idet = loc_arr(1,kdx)
                     b = t4a_excits(idet,2); d = t4a_excits(idet,4); k = t4a_excits(idet,7); l = t4a_excits(idet,8);
