                        IX(:,:) = IX(:,:) + (1d0 * t2a(b,u,k,l)) * H2B_vovv_1302(:,:,d,u)
                     end do
                     do u = 1, noa
                        IX(:,:) = IX(:,:) + (-1d0 * t2a(b,d,k,u)) * H2B_ooov_1302(:,:,u,l)
