                     if (idx/=0) then
                     do jdet = loc_vaaa22(1,idx), loc_vaaa22(2,idx)
                        v = vaaa22_excits(jdet,5); u = vaaa22_excits(jdet,6)
                        IX(:,:) = IX(:,:) + (0.5d0 * vaaa22_amps(jdet)) * V2A_oovv_1302(:,:,u,v)
