                     end do
                     do idet = loc_arr(1,kdx), loc_arr(2,kdx)
                        a = t4a_excits(idet,1); b = t4a_excits(idet,2); i = t4a_excits(idet,5); j = t4a_excits(idet,6);
                        val = 0.0d0
                        idx = idx_vaab2020(a,b,i,j)
