              subroutine t4a_p_b2(resid,&
                                      t4a_amps, t4a_excits, t4b_amps, t4b_excits,&
                                      t2a, H2A_voov_1023, H2A_oooo_1023, V2A_oovv_1023,&
                                      V2B_oovv, H2A_vvvv_3012, V2A_oovv_3012, V2B_oovv_2013,&
                                      n4aaaa, n4aaab, noa, nua,&
                                      nob, nub)
                  integer, intent(in) :: n4aaaa, n4aaab, noa, nua, nob, nub
                  real(kind=8), intent(inout) :: resid(n4aaaa)
                  !f2py intent(in,out) :: resid(0:n4aaaa-1)
                  real(kind=8), intent(inout) :: t4a_amps(n4aaaa)
                  !f2py intent(in,out) :: t4a_amps(0:n4aaaa-1)
                  integer, intent(inout) :: t4a_excits(n4aaaa,8)
                  !f2py intent(in,out) :: t4a_excits(0:n4aaaa-1,0:7)
                  real(kind=8), intent(in) :: t4b_amps(n4aaab)
                  integer, intent(in) :: t4b_excits(n4aaab,8)
                  real(kind=8), intent(in) :: t2a(nua,nua,noa,noa)
                  real(kind=8), intent(in) :: H2A_voov_1023(noa,nua,noa,nua)
                  real(kind=8), intent(in) :: H2A_oooo_1023(noa,noa,noa,noa)
