                  bt4b_amps(:) = t4b_amps(:)
                  bt4b_excits(:,:) = t4b_excits(:,:)


                  !!!! 36 passes on T4 sorted by columns (1,2,5,6,7)
                  tdims(1:5) = (/nua,nua,noa,noa,noa/)
                  tchain(1:5) = (/.false.,.true.,.false.,.true.,.true./)
                  call sort_pspace(t4a_excits, t4a_amps, n4aaaa, 5, (/1,2,5,6,7/), tdims, tchain, tnblk, tkey, toff, resid)
                  ! -0.25 * W(axidjl) * taa(bcxk), q = (a,b,i,j,k), sign -1
                  !$omp parallel default(shared) private(IX,val,a,b,c,d,i,j,k,l,x,y,u,v,w,z,r,s,t,g,h,idet,jdet,kdx,idx)
                  allocate(IX(noa))
                  !$omp do schedule(dynamic)
                  do kdx = 1, tnblk
                     if (toff(kdx+1)-1 < toff(kdx)) cycle
                     idet = toff(kdx)
                     a = t4a_excits(idet,1); b = t4a_excits(idet,2); i = t4a_excits(idet,5); j = t4a_excits(idet,6); k = t4a_excits(idet,7);
                     IX = 0.0d0
                     do u = 1, nua
                        IX(:) = IX(:) + (-1d0 * t2a(b,u,j,k)) * H2A_voov_1023(:,a,i,u)
