                                h2c_oovv_3012, h2b_vovo_2013, h2a_voov_3012, h2a_vvvv_3012, h2b_vvvv_2013, h2a_oovv_3012,&
                                h2b_oovv_2013, h2b_oovv_1023, h2c_oovv_1023, n4aaab, n4aaaa, n4aabb,&
                                noa, nua, nob, nub)
                  deallocate(h2a_vooo_1023)
                  deallocate(h2b_vooo_1023)
