                  deallocate(h2b_oovv_2013)
                  deallocate(h2b_oovv_1023)
                  deallocate(h2c_oovv_1023)

                  ! Update t4 vector
                  !$omp parallel shared(resid,t4b_excits,t4b_amps,fA_oo,fA_vv,fB_oo,fB_vv,n4aaab,shift),&
                  !$omp private(idet,a,b,c,d,i,j,k,l,denom)
                  !$omp do schedule(static)
                  do idet = 1, n4aaab
                      a = t4b_excits(idet,1); b = t4b_excits(idet,2); c = t4b_excits(idet,3); d = t4b_excits(idet,4);
                      i = t4b_excits(idet,5); j = t4b_excits(idet,6); k = t4b_excits(idet,7); l = t4b_excits(idet,8);
                      denom = fA_oo(i,i) + fA_oo(j,j) + fA_oo(k,k) + fB_oo(l,l) - fA_vv(a,a) - fA_vv(b,b) - fA_vv(c,c) - fB_vv(d,d)
                      resid(idet) = resid(idet)/(denom - shift)
                      t4b_amps(idet) = t4b_amps(idet) + resid(idet)
                  end do
                  !$omp end do
                  !$omp end parallel

              end subroutine update_t4b_p

              subroutine t4b_p_lin(resid,&
                                      t4b_amps, t4b_excits, t3a_amps, t3a_excits,&
                                      t3b_amps, t3b_excits, t4c_amps, t4c_excits,&
                                      t4a_amps, t4a_excits, H2B_ovoo, H2A_vooo,&
                                      H2B_vooo, H2B_vvvo, H2A_vvov, H2B_vvov,&
                                      H2A_oooo, H1A_oo, H2B_oooo, H1B_oo,&
                                      H2A_vvvv, H1A_vv, H2B_vvvv, H1B_vv,&
                                      H2A_voov, H2B_voov, H2B_ovvo, H2C_voov,&
                                      H2B_vovo, H2B_ovov, n4aaab, n3aaa,&
                                      n3aab, n4aabb, n4aaaa, noa,&
                                      nua, nob, nub)
                  integer, intent(in) :: n4aaab, n3aaa, n3aab, n4aabb, n4aaaa, noa, nua, nob, nub
                  real(kind=8), intent(out) :: resid(n4aaab)
                  real(kind=8), intent(inout) :: t4b_amps(n4aaab)
                  !f2py intent(in,out) :: t4b_amps(0:n4aaab-1)
                  integer, intent(inout) :: t4b_excits(n4aaab,8)
                  !f2py intent(in,out) :: t4b_excits(0:n4aaab-1,0:8-1)
                  real(kind=8), intent(in) :: t3a_amps(n3aaa)
                  integer, intent(in) :: t3a_excits(n3aaa,6)
                  real(kind=8), intent(in) :: t3b_amps(n3aab)
                  integer, intent(in) :: t3b_excits(n3aab,6)
                  real(kind=8), intent(in) :: t4c_amps(n4aabb)
                  integer, intent(in) :: t4c_excits(n4aabb,8)
                  real(kind=8), intent(in) :: t4a_amps(n4aaaa)
                  integer, intent(in) :: t4a_excits(n4aaaa,8)
                  real(kind=8), intent(in) :: H2B_ovoo(noa,nub,noa,nob)
                  real(kind=8), intent(in) :: H2A_vooo(noa,nua,noa,noa)
                  real(kind=8), intent(in) :: H2B_vooo(nob,nua,noa,nob)
                  real(kind=8), intent(in) :: H2B_vvvo(nua,nua,nub,nob)
                  real(kind=8), intent(in) :: H2A_vvov(nua,nua,nua,noa)
                  real(kind=8), intent(in) :: H2B_vvov(nub,nua,nub,noa)
                  real(kind=8), intent(in) :: H2A_oooo(noa,noa,noa,noa)
                  real(kind=8), intent(in) :: H1A_oo(noa,noa)
                  real(kind=8), intent(in) :: H2B_oooo(noa,nob,noa,nob)
                  real(kind=8), intent(in) :: H1B_oo(nob,nob)
                  real(kind=8), intent(in) :: H2A_vvvv(nua,nua,nua,nua)
                  real(kind=8), intent(in) :: H1A_vv(nua,nua)
                  real(kind=8), intent(in) :: H2B_vvvv(nua,nub,nua,nub)
                  real(kind=8), intent(in) :: H1B_vv(nub,nub)
                  real(kind=8), intent(in) :: H2A_voov(noa,nua,nua,noa)
                  real(kind=8), intent(in) :: H2B_voov(nob,nub,nua,noa)
                  real(kind=8), intent(in) :: H2B_ovvo(noa,nua,nub,nob)
                  real(kind=8), intent(in) :: H2C_voov(nob,nub,nub,nob)
                  real(kind=8), intent(in) :: H2B_vovo(nob,nua,nua,nob)
                  real(kind=8), intent(in) :: H2B_ovov(noa,nub,nub,noa)
                  integer, allocatable :: idx_table(:,:,:,:), loc_arr(:,:), block_off(:)
                  integer(kind=8), allocatable :: block_key(:)
                  integer :: kdims(6), nblock
                  logical :: kchain(6)
                  real(kind=8), allocatable :: t3_amps_buff(:), t4_amps_buff(:)
                  integer, allocatable :: t3_excits_buff(:,:), t4_excits_buff(:,:)
                  real(kind=8) :: hmatel, hmatel1, hmatel2, hmatel3, hmatel4
