                  !$omp parallel shared(resid,&
                  !$omp t4b_excits,&
                  !$omp t4b_amps,&
                  !$omp nblock,block_key,block_off,kdims,kchain,&
                  !$omp H2B_ovov,&
                  !$omp noa,nua,nob,nub,n4aaab),&
                  !$omp private(hmatel,a,b,c,d,i,j,k,l,e,f,m,n,h,idet,jdet,&
                  !$omp idx)
                  !$omp do schedule(static)
                  do idet = 1, n4aaab
                     a = t4b_excits(idet,1); b = t4b_excits(idet,2); c = t4b_excits(idet,3); d = t4b_excits(idet,4);
                     i = t4b_excits(idet,5); j = t4b_excits(idet,6); k = t4b_excits(idet,7); l = t4b_excits(idet,8);
                     ! (1)
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,c,j,k,l/), 6, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        h = t4b_excits(jdet,4); m = t4b_excits(jdet,5);
                        ! compute < ijklabcd | h2b(ovov) | mjkl~abch~ >
                        !hmatel = -h2b_ovov(m,d,i,h)
                        hmatel = -h2b_ovov(m,h,d,i)
                        resid(idet) = resid(idet) + hmatel * t4b_amps(jdet)
                     end do
                     end if
                     ! (ij)
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,c,i,k,l/), 6, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        h = t4b_excits(jdet,4); m = t4b_excits(jdet,5);
                        ! compute < ijklabcd | h2b(ovov) | mikl~abch~ >
                        !hmatel = h2b_ovov(m,d,j,h)
                        hmatel = h2b_ovov(m,h,d,j)
                        resid(idet) = resid(idet) + hmatel * t4b_amps(jdet)
                     end do
                     end if
                     ! (ik)
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,c,i,j,l/), 6, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        h = t4b_excits(jdet,4); m = t4b_excits(jdet,5);
                        ! compute < ijklabcd | h2b(ovov) | mijl~abch~ >
                        !hmatel = -h2b_ovov(m,d,k,h)
                        hmatel = -h2b_ovov(m,h,d,k)
                        resid(idet) = resid(idet) + hmatel * t4b_amps(jdet)
                     end do
                     end if
                  end do
                  !$omp end do
                  !$omp end parallel
                  !!!! END OMP PARALLEL SECTION !!!!
                  ! deallocate sorting arrays
                  deallocate(block_key,block_off)

                  call release_sort_workspace()
              end subroutine t4b_p_lin

