                     r1 = t3a_excits(idet,1); r2 = t3a_excits(idet,2); r3 = t3a_excits(idet,3); r4 = t3a_excits(idet,4); r5 = t3a_excits(idet,5); r6 = t3a_excits(idet,6);
                     jdet = 3*(idet-1)
                     vaaa31_excits(jdet+1,:) = (/r1,r2,r3,r4,r5,r6/); vaaa31_amps(jdet+1) = t3a_amps(idet)
                     vaaa31_excits(jdet+2,:) = (/r1,r2,r3,r5,r4,r6/); vaaa31_amps(jdet+2) = -t3a_amps(idet)
                     vaaa31_excits(jdet+3,:) = (/r1,r2,r3,r6,r4,r5/); vaaa31_amps(jdet+3) = t3a_amps(idet)
