                     r1 = t3a_excits(idet,1); r2 = t3a_excits(idet,2); r3 = t3a_excits(idet,3); r4 = t3a_excits(idet,4); r5 = t3a_excits(idet,5); r6 = t3a_excits(idet,6);
                     jdet = 3*(idet-1)
