                  call sort4(vaab2101_excits, vaab2101_amps, loc_vaab2101, idx_vaab2101, (/1,2,3,4/), nua, nua, nub, nob, nloc_vaab2101, 1*n3aab)
                  ! view vaab1021: every t3b row once per key placement, key columns first
