              subroutine t4b_p_b2(resid,&
                                      t4b_amps, t4b_excits, t4a_amps, t4a_excits,&
                                      t4c_amps, t4c_excits, t2a, t2b,&
                                      H2B_ovvo, H2A_oooo_1023, H2B_ovov, H2B_oooo,&
                                      H2A_voov_1023, V2A_oovv_1023, V2B_oovv, H2B_voov_3012,&
                                      V2B_oovv_3012, V2C_oovv_3012, H2B_vovo_2013, H2A_voov_3012,&
                                      H2A_vvvv_3012, H2B_vvvv_2013, V2A_oovv_3012, V2B_oovv_2013,&
                                      V2B_oovv_1023, V2C_oovv_1023, n4aaab, n4aaaa,&
                                      n4aabb, noa, nua, nob,&
                                      nub)
                  integer, intent(in) :: n4aaab, n4aaaa, n4aabb, noa, nua, nob, nub
                  real(kind=8), intent(inout) :: resid(n4aaab)
                  !f2py intent(in,out) :: resid(0:n4aaab-1)
                  real(kind=8), intent(inout) :: t4b_amps(n4aaab)
                  !f2py intent(in,out) :: t4b_amps(0:n4aaab-1)
                  integer, intent(inout) :: t4b_excits(n4aaab,8)
                  !f2py intent(in,out) :: t4b_excits(0:n4aaab-1,0:7)
                  real(kind=8), intent(in) :: t4a_amps(n4aaaa)
                  integer, intent(in) :: t4a_excits(n4aaaa,8)
                  real(kind=8), intent(in) :: t4c_amps(n4aabb)
                  integer, intent(in) :: t4c_excits(n4aabb,8)
                  real(kind=8), intent(in) :: t2a(nua,nua,noa,noa)
                  real(kind=8), intent(in) :: t2b(nua,nub,noa,nob)
                  real(kind=8), intent(in) :: H2B_ovvo(noa,nub,nua,nob)
                  real(kind=8), intent(in) :: H2A_oooo_1023(noa,noa,noa,noa)
                  real(kind=8), intent(in) :: H2B_ovov(noa,nub,noa,nub)
                  real(kind=8), intent(in) :: H2B_oooo(noa,nob,noa,nob)
                  real(kind=8), intent(in) :: H2A_voov_1023(noa,nua,noa,nua)
                  real(kind=8), intent(in) :: V2A_oovv_1023(noa,noa,nua,nua)
                  real(kind=8), intent(in) :: V2B_oovv(noa,nob,nua,nub)
                  real(kind=8), intent(in) :: H2B_voov_3012(nub,nua,nob,noa)
                  real(kind=8), intent(in) :: V2B_oovv_3012(nub,noa,nob,nua)
                  real(kind=8), intent(in) :: V2C_oovv_3012(nub,nob,nob,nub)
                  real(kind=8), intent(in) :: H2B_vovo_2013(nua,nua,nob,nob)
                  real(kind=8), intent(in) :: H2A_voov_3012(nua,nua,noa,noa)
                  real(kind=8), intent(in) :: H2A_vvvv_3012(nua,nua,nua,nua)
                  real(kind=8), intent(in) :: H2B_vvvv_2013(nua,nua,nub,nub)
                  real(kind=8), intent(in) :: V2A_oovv_3012(nua,noa,noa,nua)
                  real(kind=8), intent(in) :: V2B_oovv_2013(nua,noa,nob,nub)
                  real(kind=8), intent(in) :: V2B_oovv_1023(nob,noa,nua,nub)
                  real(kind=8), intent(in) :: V2C_oovv_1023(nob,nob,nub,nub)
                  integer, allocatable :: idx_table(:,:,:,:), loc_arr(:,:), toff(:), soff(:)
                  integer(kind=8), allocatable :: tkey(:), skey(:)
                  integer :: tdims(8), sdims(8), tnblk, snblk
                  logical :: tchain(8), schain(8)
                  real(kind=8), allocatable :: bt4a_amps(:)
                  integer, allocatable :: bt4a_excits(:,:)
                  real(kind=8), allocatable :: bt4b_amps(:)
                  integer, allocatable :: bt4b_excits(:,:)
                  real(kind=8), allocatable :: bt4c_amps(:)
                  integer, allocatable :: bt4c_excits(:,:)
                  real(kind=8), allocatable :: IX(:)
                  real(kind=8) :: val
                  integer :: a, b, c, d, i, j, k, l, x, y, u, v, w, z, r, s, t, g, h
                  integer :: r1, r2, r3, r4, r5, r6, idet, jdet, kdx, idx, nloc
                  allocate(bt4a_amps(n4aaaa),bt4a_excits(n4aaaa,8))
                  bt4a_amps(:) = t4a_amps(:)
                  bt4a_excits(:,:) = t4a_excits(:,:)
                  allocate(bt4b_amps(n4aaab),bt4b_excits(n4aaab,8))
                  bt4b_amps(:) = t4b_amps(:)
                  bt4b_excits(:,:) = t4b_excits(:,:)
                  allocate(bt4c_amps(n4aabb),bt4c_excits(n4aabb,8))
                  bt4c_amps(:) = t4c_amps(:)
                  bt4c_excits(:,:) = t4c_excits(:,:)


                  !!!! 25 passes on T4 sorted by columns (1,4,5,6,8)
                  tdims(1:5) = (/nua,nub,noa,noa,nob/)
                  tchain(1:5) = (/.false.,.false.,.false.,.true.,.false./)
                  call sort_pspace(t4b_excits, t4b_amps, n4aaab, 5, (/1,4,5,6,8/), tdims, tchain, tnblk, tkey, toff, resid)
                  ! -0.25 * W(xdlcjk) * taa(abix), q = (a,d,i,j,l), sign +1
                  !$omp parallel default(shared) private(IX,val,a,b,c,d,i,j,k,l,x,y,u,v,w,z,r,s,t,g,h,idet,jdet,kdx,idx)
                  allocate(IX(noa))
                  !$omp do schedule(dynamic)
                  do kdx = 1, tnblk
                     if (toff(kdx+1)-1 < toff(kdx)) cycle
                     idet = toff(kdx)
                     a = t4b_excits(idet,1); d = t4b_excits(idet,4); i = t4b_excits(idet,5); j = t4b_excits(idet,6); l = t4b_excits(idet,8);
                     IX = 0.0d0
                     do u = 1, nua
                        IX(:) = IX(:) + (-1d0 * t2a(a,u,i,j)) * H2B_ovvo(:,d,u,l)
                     end do
                     do idet = toff(kdx), toff(kdx+1)-1
                        b = t4b_excits(idet,2); c = t4b_excits(idet,3); k = t4b_excits(idet,7);
                        val = 0.0d0
