                  call sort4(t4c_excits, t4c_amps, loc_arr, idx_table, (/2,3,7,8/), nua, nub, nob, nob, nloc, n4aabb, resid)
                  ! -0.25 * I3C_vovvoo(axcylk) * taab(bydjix), q = (b,c,k,l), sign -1
