                     end do
                     do u = 1, nub
                        IX(:,:) = IX(:,:) + (1d0 * t2c(c,u,k,l)) * H2B_vovv_1203(:,:,b,u)
                     end do
                     do u = 1, noa
                        IX(:,:) = IX(:,:) + (1d0 * t2b(b,c,u,l)) * H2B_oovo_1203(:,:,u,k)
                     end do
                     do idet = loc_arr(1,kdx), loc_arr(2,kdx)
                        a = t4c_excits(idet,1); d = t4c_excits(idet,4); i = t4c_excits(idet,5); j = t4c_excits(idet,6);
                        val = 0.0d0
                        idx = idx_vaab1120(a,d,i,j)
                        if (idx/=0) then
                        do jdet = loc_vaab1120(1,idx), loc_vaab1120(2,idx)
                           y = vaab1120_excits(jdet,5); x = vaab1120_excits(jdet,6)
                           val = val + vaab1120_amps(jdet) * ((-1)*IX(x,y))
                        end do
                        end if
                        resid(idet) = resid(idet) + 1d0 * val
                     end do
                  end do
                  !$omp end do
                  deallocate(IX)
                  !$omp end parallel
                  !!!! 1 passes on T4 sorted by columns (2,4,7,8)
                  call get_index_table(idx_table, (/2,nua/), (/2,nub/), (/1,nob-1/), (/-1,nob/), nua, nub, nob, nob)
                  call sort4(t4c_excits, t4c_amps, loc_arr, idx_table, (/2,4,7,8/), nua, nub, nob, nob, nloc, n4aabb, resid)
                  ! -0.25 * I3C_vovvoo(axcylk) * taab(bydjix), q = (b,d,k,l), sign +1
                  !$omp parallel default(shared) private(IX,val,a,b,c,d,i,j,k,l,x,y,u,v,w,z,r,s,t,g,h,idet,jdet,kdx,idx)
