              subroutine t4c_p_b2(resid,&
                                      t4c_amps, t4c_excits, t4b_amps, t4b_excits,&
                                      t4d_amps, t4d_excits, t2a, t2b,&
                                      t2c, H2C_voov_1023, H2B_voov_1023, H2B_vovo_1023,&
                                      H2C_oooo_1023, V2B_oovv_1023, V2C_oovv_1023, H2A_voov_1023,&
                                      H2B_ovov, H2A_oooo_1023, H2B_oooo, V2A_oovv_1023,&
                                      V2B_oovv, H2B_ovvo_2013, H2B_vvvv_2013, V2A_oovv_3012,&
                                      V2B_oovv_2013, H2B_ovvo, H2A_vvvv_3012, H2C_vvvv_3012,&
                                      V2B_oovv_3012, V2C_oovv_3012, n4aabb, n4aaab,&
                                      n4abbb, noa, nua, nob,&
                                      nub)
                  integer, intent(in) :: n4aabb, n4aaab, n4abbb, noa, nua, nob, nub
                  real(kind=8), intent(inout) :: resid(n4aabb)
                  !f2py intent(in,out) :: resid(0:n4aabb-1)
                  real(kind=8), intent(inout) :: t4c_amps(n4aabb)
                  !f2py intent(in,out) :: t4c_amps(0:n4aabb-1)
                  integer, intent(inout) :: t4c_excits(n4aabb,8)
                  !f2py intent(in,out) :: t4c_excits(0:n4aabb-1,0:7)
                  real(kind=8), intent(in) :: t4b_amps(n4aaab)
                  integer, intent(in) :: t4b_excits(n4aaab,8)
                  real(kind=8), intent(in) :: t4d_amps(n4abbb)
                  integer, intent(in) :: t4d_excits(n4abbb,8)
                  real(kind=8), intent(in) :: t2a(nua,nua,noa,noa)
                  real(kind=8), intent(in) :: t2b(nua,nub,noa,nob)
                  real(kind=8), intent(in) :: t2c(nub,nub,nob,nob)
                  real(kind=8), intent(in) :: H2C_voov_1023(nob,nub,nob,nub)
                  real(kind=8), intent(in) :: H2B_voov_1023(nob,nua,noa,nub)
                  real(kind=8), intent(in) :: H2B_vovo_1023(nob,nua,nua,nob)
                  real(kind=8), intent(in) :: H2C_oooo_1023(nob,nob,nob,nob)
                  real(kind=8), intent(in) :: V2B_oovv_1023(nob,noa,nua,nub)
                  real(kind=8), intent(in) :: V2C_oovv_1023(nob,nob,nub,nub)
                  real(kind=8), intent(in) :: H2A_voov_1023(noa,nua,noa,nua)
                  real(kind=8), intent(in) :: H2B_ovov(noa,nub,noa,nub)
                  real(kind=8), intent(in) :: H2A_oooo_1023(noa,noa,noa,noa)
                  real(kind=8), intent(in) :: H2B_oooo(noa,nob,noa,nob)
                  real(kind=8), intent(in) :: V2A_oovv_1023(noa,noa,nua,nua)
                  real(kind=8), intent(in) :: V2B_oovv(noa,nob,nua,nub)
                  real(kind=8), intent(in) :: H2B_ovvo_2013(nua,noa,nub,nob)
                  real(kind=8), intent(in) :: H2B_vvvv_2013(nua,nua,nub,nub)
                  real(kind=8), intent(in) :: V2A_oovv_3012(nua,noa,noa,nua)
                  real(kind=8), intent(in) :: V2B_oovv_2013(nua,noa,nob,nub)
                  real(kind=8), intent(in) :: H2B_ovvo(noa,nub,nua,nob)
                  real(kind=8), intent(in) :: H2A_vvvv_3012(nua,nua,nua,nua)
                  real(kind=8), intent(in) :: H2C_vvvv_3012(nub,nub,nub,nub)
                  real(kind=8), intent(in) :: V2B_oovv_3012(nub,noa,nob,nua)
                  real(kind=8), intent(in) :: V2C_oovv_3012(nub,nob,nob,nub)
                  integer, allocatable :: idx_table(:,:,:,:), loc_arr(:,:), toff(:), soff(:)
                  integer(kind=8), allocatable :: tkey(:), skey(:)
                  integer :: tdims(8), sdims(8), tnblk, snblk
                  logical :: tchain(8), schain(8)
                  real(kind=8), allocatable :: bt4b_amps(:)
                  integer, allocatable :: bt4b_excits(:,:)
                  real(kind=8), allocatable :: bt4c_amps(:)
                  integer, allocatable :: bt4c_excits(:,:)
                  real(kind=8), allocatable :: bt4d_amps(:)
                  integer, allocatable :: bt4d_excits(:,:)
                  real(kind=8), allocatable :: IX(:)
                  real(kind=8) :: val
                  integer :: a, b, c, d, i, j, k, l, x, y, u, v, w, z, r, s, t, g, h
                  integer :: r1, r2, r3, r4, r5, r6, idet, jdet, kdx, idx, nloc
                  allocate(bt4b_amps(n4aaab),bt4b_excits(n4aaab,8))
                  bt4b_amps(:) = t4b_amps(:)
                  bt4b_excits(:,:) = t4b_excits(:,:)
                  allocate(bt4c_amps(n4aabb),bt4c_excits(n4aabb,8))
                  bt4c_amps(:) = t4c_amps(:)
                  bt4c_excits(:,:) = t4c_excits(:,:)
                  allocate(bt4d_amps(n4abbb),bt4d_excits(n4abbb,8))
                  bt4d_amps(:) = t4d_amps(:)
                  bt4d_excits(:,:) = t4d_excits(:,:)


                  !!!! 23 passes on T4 sorted by columns (1,3,5,7,8)
                  tdims(1:5) = (/nua,nub,noa,nob,nob/)
                  tchain(1:5) = (/.false.,.false.,.false.,.false.,.true./)
                  call sort_pspace(t4c_excits, t4c_amps, n4aabb, 5, (/1,3,5,7,8/), tdims, tchain, tnblk, tkey, toff, resid)
                  ! -1 * W(cxkbjl) * tab(adix), q = (a,c,i,k,l), sign +1
                  !$omp parallel default(shared) private(IX,val,a,b,c,d,i,j,k,l,x,y,u,v,w,z,r,s,t,g,h,idet,jdet,kdx,idx)
                  allocate(IX(nob))
                  !$omp do schedule(dynamic)
                  do kdx = 1, tnblk
                     if (toff(kdx+1)-1 < toff(kdx)) cycle
                     idet = toff(kdx)
                     a = t4c_excits(idet,1); c = t4c_excits(idet,3); i = t4c_excits(idet,5); k = t4c_excits(idet,7); l = t4c_excits(idet,8);
                     IX = 0.0d0
                     do u = 1, nub
                        IX(:) = IX(:) + (1d0 * t2b(a,u,i,l)) * H2C_voov_1023(:,c,k,u)
                     end do
                     do idet = toff(kdx), toff(kdx+1)-1
                        b = t4c_excits(idet,2); d = t4c_excits(idet,4); j = t4c_excits(idet,6);
                        val = 0.0d0
                        do x = 1, nob
                           val = val + IX(x) * t2b(b,d,j,x)
                        end do
                        resid(idet) = resid(idet) - 1d0 * val
                     end do
                  end do
                  !$omp end do
                  deallocate(IX)
                  !$omp end parallel
                  ! -1 * W(cxkbjl) * tab(adix), q = (a,c,i,k,l), sign -1
                  !$omp parallel default(shared) private(IX,val,a,b,c,d,i,j,k,l,x,y,u,v,w,z,r,s,t,g,h,idet,jdet,kdx,idx)
                  allocate(IX(nob))
