                     idet = toff(kdx)
                     a = t4c_excits(idet,1); c = t4c_excits(idet,3); i = t4c_excits(idet,5); k = t4c_excits(idet,7); l = t4c_excits(idet,8);
                     IX = 0.0d0
                     do u = 1, nub
                        IX(:) = IX(:) + (1d0 * t2b(a,u,i,k)) * H2C_voov_1023(:,c,l,u)
                     end do
                     do idet = toff(kdx), toff(kdx+1)-1
                        b = t4c_excits(idet,2); d = t4c_excits(idet,4); j = t4c_excits(idet,6);
                        val = 0.0d0
                        do x = 1, nob
                           val = val + IX(x) * t2b(b,d,j,x)
                        end do
                        resid(idet) = resid(idet) + 1d0 * val
                     end do
                  end do
                  !$omp end do
                  deallocate(IX)
                  !$omp end parallel
                  ! -0.5 * W(axickl) * tab(bdjx), q = (a,c,i,k,l), sign +1
                  !$omp parallel default(shared) private(IX,val,a,b,c,d,i,j,k,l,x,y,u,v,w,z,r,s,t,g,h,idet,jdet,kdx,idx)
                  allocate(IX(nob))
                  !$omp do schedule(dynamic)
                  do kdx = 1, tnblk
                     if (toff(kdx+1)-1 < toff(kdx)) cycle
                     idet = toff(kdx)
                     a = t4c_excits(idet,1); c = t4c_excits(idet,3); i = t4c_excits(idet,5); k = t4c_excits(idet,7); l = t4c_excits(idet,8);
                     IX = 0.0d0
                     do u = 1, nub
                        IX(:) = IX(:) + (1d0 * t2c(c,u,k,l)) * H2B_voov_1023(:,a,i,u)
                     end do
                     do idet = toff(kdx), toff(kdx+1)-1
                        b = t4c_excits(idet,2); d = t4c_excits(idet,4); j = t4c_excits(idet,6);
                        val = 0.0d0
                        do x = 1, nob
                           val = val + IX(x) * t2b(b,d,j,x)
                        end do
                        resid(idet) = resid(idet) - 1d0 * val
                     end do
                  end do
                  !$omp end do
                  deallocate(IX)
                  !$omp end parallel
                  ! -1 * W(bxlcjk) * tab(adix), q = (a,c,i,k,l), sign -1
                  !$omp parallel default(shared) private(IX,val,a,b,c,d,i,j,k,l,x,y,u,v,w,z,r,s,t,g,h,idet,jdet,kdx,idx)
                  allocate(IX(nob))
                  !$omp do schedule(dynamic)
                  do kdx = 1, tnblk
                     if (toff(kdx+1)-1 < toff(kdx)) cycle
                     idet = toff(kdx)
                     a = t4c_excits(idet,1); c = t4c_excits(idet,3); i = t4c_excits(idet,5); k = t4c_excits(idet,7); l = t4c_excits(idet,8);
                     IX = 0.0d0
                     do u = 1, nua
                        IX(:) = IX(:) + (1d0 * t2b(u,c,i,l)) * H2B_vovo_1023(:,a,u,k)
                     end do
                     do idet = toff(kdx), toff(kdx+1)-1
                        b = t4c_excits(idet,2); d = t4c_excits(idet,4); j = t4c_excits(idet,6);
                        val = 0.0d0
