                     do p3 = 1, nob
                        do p2 = 1, nob
                           do p1 = 1, nob
                              h2c_oooo_1023(p1,p2,p3,p4) = H2C_oooo(p2,p1,p3,p4)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2b_vovo_1023(nob,nua,nua,nob))
                  do p4 = 1, nob
                     do p3 = 1, nua
                        do p2 = 1, nua
                           do p1 = 1, nob
                              h2b_vovo_1023(p1,p2,p3,p4) = H2B_vovo(p2,p1,p3,p4)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2b_oooo_1023(nob,noa,noa,nob))
                  do p4 = 1, nob
                     do p3 = 1, noa
                        do p2 = 1, noa
                           do p1 = 1, nob
                              h2b_oooo_1023(p1,p2,p3,p4) = H2B_oooo(p2,p1,p3,p4)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2c_voov_1023(nob,nub,nob,nub))
                  do p4 = 1, nub
                     do p3 = 1, nob
                        do p2 = 1, nub
                           do p1 = 1, nob
                              h2c_voov_1023(p1,p2,p3,p4) = H2C_voov(p2,p1,p3,p4)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2c_oovv_1023(nob,nob,nub,nub))
                  do p4 = 1, nub
                     do p3 = 1, nub
                        do p2 = 1, nob
                           do p1 = 1, nob
                              h2c_oovv_1023(p1,p2,p3,p4) = H2C_oovv(p2,p1,p3,p4)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2b_oovv_1023(nob,noa,nua,nub))
                  do p4 = 1, nub
                     do p3 = 1, nua
                        do p2 = 1, noa
                           do p1 = 1, nob
                              h2b_oovv_1023(p1,p2,p3,p4) = H2B_oovv(p2,p1,p3,p4)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2b_ovvo_2013(nua,noa,nub,nob))
                  do p4 = 1, nob
                     do p3 = 1, nub
                        do p2 = 1, noa
                           do p1 = 1, nua
                              h2b_ovvo_2013(p1,p2,p3,p4) = H2B_ovvo(p2,p3,p1,p4)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2b_oovv_2013(nua,noa,nob,nub))
                  do p4 = 1, nub
                     do p3 = 1, nob
                        do p2 = 1, noa
                           do p1 = 1, nua
                              h2b_oovv_2013(p1,p2,p3,p4) = H2B_oovv(p2,p3,p1,p4)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2a_oovv_3012(nua,noa,noa,nua))
                  do p4 = 1, nua
                     do p3 = 1, noa
                        do p2 = 1, noa
                           do p1 = 1, nua
                              h2a_oovv_3012(p1,p2,p3,p4) = H2A_oovv(p2,p3,p4,p1)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2b_ovov_3012(nub,noa,nub,noa))
                  do p4 = 1, noa
                     do p3 = 1, nub
                        do p2 = 1, noa
                           do p1 = 1, nub
                              h2b_ovov_3012(p1,p2,p3,p4) = H2B_ovov(p2,p3,p4,p1)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2c_voov_3012(nub,nub,nob,nob))
                  do p4 = 1, nob
                     do p3 = 1, nob
                        do p2 = 1, nub
                           do p1 = 1, nub
                              h2c_voov_3012(p1,p2,p3,p4) = H2C_voov(p2,p3,p4,p1)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2c_vvvv_3012(nub,nub,nub,nub))
                  do p4 = 1, nub
                     do p3 = 1, nub
                        do p2 = 1, nub
                           do p1 = 1, nub
                              h2c_vvvv_3012(p1,p2,p3,p4) = H2C_vvvv(p2,p3,p4,p1)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2b_vvvv_3012(nub,nua,nub,nua))
                  do p4 = 1, nua
                     do p3 = 1, nub
                        do p2 = 1, nua
                           do p1 = 1, nub
                              h2b_vvvv_3012(p1,p2,p3,p4) = H2B_vvvv(p2,p3,p4,p1)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2c_oovv_3012(nub,nob,nob,nub))
                  do p4 = 1, nub
                     do p3 = 1, nob
                        do p2 = 1, nob
                           do p1 = 1, nub
                              h2c_oovv_3012(p1,p2,p3,p4) = H2C_oovv(p2,p3,p4,p1)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2b_oovv_3012(nub,noa,nob,nua))
                  do p4 = 1, nua
                     do p3 = 1, nob
                        do p2 = 1, noa
                           do p1 = 1, nub
                              h2b_oovv_3012(p1,p2,p3,p4) = H2B_oovv(p2,p3,p4,p1)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2a_oovv_1023(noa,noa,nua,nua))
                  do p4 = 1, nua
                     do p3 = 1, nua
                        do p2 = 1, noa
                           do p1 = 1, noa
                              h2a_oovv_1023(p1,p2,p3,p4) = H2A_oovv(p2,p1,p3,p4)
                           end do
                        end do
                     end do
                  end do

                  ! (H(2) * T3 + H(2) * T4)_C linear terms
                  call t4d_p_lin(resid, t4d_amps, t4d_excits, t3d_amps, t3d_excits, t3c_amps,&
                                 t3c_excits, t4c_amps, t4c_excits, t4e_amps, t4e_excits, h2b_vooo_1023,&
                                 h2c_vooo_1023, H2B_ovoo, h2b_vvov_3012, h2c_vvov_3012, h2b_vvvo_2013, H2C_oooo,&
                                 H1B_oo, H2B_oooo, H1A_oo, h2c_vvvv_2301, h1b_vv_10, h2b_vvvv_2301,&
                                 h1a_vv_10, h2c_voov_1302, h2b_ovvo_0213, h2b_voov_1302, h2a_voov_1302, h2b_ovov_0312,&
                                 h2b_vovo_1203, n4abbb, n3bbb, n3abb, n4aabb, n4bbbb,&
                                 noa, nua, nob, nub)
                  ! (I(T2, T3) * T3)_C terms
                  call t4d_p_b3(resid, t4d_amps, t4d_excits, t3b_amps, t3b_excits, t3c_amps,&
                                t3c_excits, t3d_amps, t3d_excits, t2b, t2c, H2C_ooov,&
                                H2C_oovv, H2B_ooov, H2B_oovo, H2B_oovv, h2c_vovv_2301, h2b_vovv_2301,&
                                h2b_ovvv_2301, h2c_ooov_1302, h2c_vovv_1302, h2b_ooov_1302, h2b_vovv_1302, h2c_oovv_1302,&
                                h2b_oovv_1302, h2b_oovo_0213, h2a_ooov_1302, h2b_ovvv_0213, h2a_vovv_1302, h2a_oovv_1302,&
                                h2b_ooov_0312, h2b_ovvv_0312, h2b_oovv_0312, h2b_vovv_1203, h2b_oovo_1203, n4abbb,&
                                n3aab, n3abb, n3bbb, noa, nua, nob,&
                                nub)
                  ! (I(T2, T4) * T2)_C and (H * T2 * T2)_C terms
                  call t4d_p_b2(resid, t4d_amps, t4d_excits, t4c_amps, t4c_excits, t4e_amps,&
                                t4e_excits, t2b, t2c, h2b_voov_1023, h2c_oooo_1023, h2b_vovo_1023,&
                                h2b_oooo_1023, h2c_voov_1023, h2c_oovv_1023, h2b_oovv_1023, h2b_ovvo_2013, h2b_oovv_2013,&
                                h2a_oovv_3012, h2b_ovov_3012, h2c_voov_3012, h2c_vvvv_3012, h2b_vvvv_3012, h2c_oovv_3012,&
                                h2b_oovv_3012, H2B_oovv, h2a_oovv_1023, n4abbb, n4aabb, n4bbbb,&
                                noa, nua, nob, nub)
                  deallocate(h2b_vooo_1023)
                  deallocate(h2c_vooo_1023)
                  deallocate(h2b_vvov_3012)
                  deallocate(h2c_vvov_3012)
                  deallocate(h2b_vvvo_2013)
                  deallocate(h2c_vvvv_2301)
                  deallocate(h1b_vv_10)
                  deallocate(h2b_vvvv_2301)
                  deallocate(h1a_vv_10)
                  deallocate(h2c_voov_1302)
                  deallocate(h2b_ovvo_0213)
                  deallocate(h2b_voov_1302)
                  deallocate(h2a_voov_1302)
                  deallocate(h2b_ovov_0312)
                  deallocate(h2b_vovo_1203)
                  deallocate(h2c_vovv_2301)
                  deallocate(h2b_vovv_2301)
                  deallocate(h2b_ovvv_2301)
                  deallocate(h2c_ooov_1302)
                  deallocate(h2c_vovv_1302)
                  deallocate(h2b_ooov_1302)
                  deallocate(h2b_vovv_1302)
                  deallocate(h2c_oovv_1302)
                  deallocate(h2b_oovv_1302)
                  deallocate(h2b_oovo_0213)
                  deallocate(h2a_ooov_1302)
                  deallocate(h2b_ovvv_0213)
                  deallocate(h2a_vovv_1302)
                  deallocate(h2a_oovv_1302)
                  deallocate(h2b_ooov_0312)
                  deallocate(h2b_ovvv_0312)
                  deallocate(h2b_oovv_0312)
                  deallocate(h2b_vovv_1203)
                  deallocate(h2b_oovo_1203)
                  deallocate(h2b_voov_1023)
                  deallocate(h2c_oooo_1023)
                  deallocate(h2b_vovo_1023)
                  deallocate(h2b_oooo_1023)
                  deallocate(h2c_voov_1023)
                  deallocate(h2c_oovv_1023)
                  deallocate(h2b_oovv_1023)
                  deallocate(h2b_ovvo_2013)
                  deallocate(h2b_oovv_2013)
                  deallocate(h2a_oovv_3012)
                  deallocate(h2b_ovov_3012)
                  deallocate(h2c_voov_3012)
                  deallocate(h2c_vvvv_3012)
                  deallocate(h2b_vvvv_3012)
                  deallocate(h2c_oovv_3012)
                  deallocate(h2b_oovv_3012)
                  deallocate(h2a_oovv_1023)

                  ! Update t4 vector
                  !$omp parallel shared(resid,t4d_excits,t4d_amps,fA_oo,fA_vv,fB_oo,fB_vv,n4abbb,shift),&
                  !$omp private(idet,a,b,c,d,i,j,k,l,denom)
                  !$omp do schedule(static)
                  do idet = 1, n4abbb
                      a = t4d_excits(idet,1); b = t4d_excits(idet,2); c = t4d_excits(idet,3); d = t4d_excits(idet,4);
                      i = t4d_excits(idet,5); j = t4d_excits(idet,6); k = t4d_excits(idet,7); l = t4d_excits(idet,8);
                      denom = fA_oo(i,i) + fB_oo(j,j) + fB_oo(k,k) + fB_oo(l,l) - fA_vv(a,a) - fB_vv(b,b) - fB_vv(c,c) - fB_vv(d,d)
                      resid(idet) = resid(idet)/(denom - shift)
                      t4d_amps(idet) = t4d_amps(idet) + resid(idet)
                  end do
                  !$omp end do
                  !$omp end parallel

              end subroutine update_t4d_p

              subroutine t4d_p_lin(resid,&
                                      t4d_amps, t4d_excits, t3d_amps, t3d_excits,&
                                      t3c_amps, t3c_excits, t4c_amps, t4c_excits,&
                                      t4e_amps, t4e_excits, H2B_vooo, H2C_vooo,&
                                      H2B_ovoo, H2B_vvov, H2C_vvov, H2B_vvvo,&
                                      H2C_oooo, H1B_oo, H2B_oooo, H1A_oo,&
                                      H2C_vvvv, H1B_vv, H2B_vvvv, H1A_vv,&
                                      H2C_voov, H2B_ovvo, H2B_voov, H2A_voov,&
                                      H2B_ovov, H2B_vovo, n4abbb, n3bbb,&
                                      n3abb, n4aabb, n4bbbb, noa,&
                                      nua, nob, nub)
                  integer, intent(in) :: n4abbb, n3bbb, n3abb, n4aabb, n4bbbb, noa, nua, nob, nub
                  real(kind=8), intent(out) :: resid(n4abbb)
                  real(kind=8), intent(inout) :: t4d_amps(n4abbb)
                  !f2py intent(in,out) :: t4d_amps(0:n4abbb-1)
                  integer, intent(inout) :: t4d_excits(n4abbb,8)
                  !f2py intent(in,out) :: t4d_excits(0:n4abbb-1,0:8-1)
                  real(kind=8), intent(in) :: t3d_amps(n3bbb)
                  integer, intent(in) :: t3d_excits(n3bbb,6)
                  real(kind=8), intent(in) :: t3c_amps(n3abb)
                  integer, intent(in) :: t3c_excits(n3abb,6)
                  real(kind=8), intent(in) :: t4c_amps(n4aabb)
                  integer, intent(in) :: t4c_excits(n4aabb,8)
                  real(kind=8), intent(in) :: t4e_amps(n4bbbb)
                  integer, intent(in) :: t4e_excits(n4bbbb,8)
                  real(kind=8), intent(in) :: H2B_vooo(nob,nua,noa,nob)
                  real(kind=8), intent(in) :: H2C_vooo(nob,nub,nob,nob)
                  real(kind=8), intent(in) :: H2B_ovoo(noa,nub,noa,nob)
                  real(kind=8), intent(in) :: H2B_vvov(nub,nua,nub,noa)
                  real(kind=8), intent(in) :: H2C_vvov(nub,nub,nub,nob)
                  real(kind=8), intent(in) :: H2B_vvvo(nua,nua,nub,nob)
                  real(kind=8), intent(in) :: H2C_oooo(nob,nob,nob,nob)
                  real(kind=8), intent(in) :: H1B_oo(nob,nob)
                  real(kind=8), intent(in) :: H2B_oooo(noa,nob,noa,nob)
                  real(kind=8), intent(in) :: H1A_oo(noa,noa)
                  real(kind=8), intent(in) :: H2C_vvvv(nub,nub,nub,nub)
                  real(kind=8), intent(in) :: H1B_vv(nub,nub)
                  real(kind=8), intent(in) :: H2B_vvvv(nua,nub,nua,nub)
                  real(kind=8), intent(in) :: H1A_vv(nua,nua)
                  real(kind=8), intent(in) :: H2C_voov(nob,nub,nub,nob)
                  real(kind=8), intent(in) :: H2B_ovvo(noa,nua,nub,nob)
                  real(kind=8), intent(in) :: H2B_voov(nob,nub,nua,noa)
                  real(kind=8), intent(in) :: H2A_voov(noa,nua,nua,noa)
                  real(kind=8), intent(in) :: H2B_ovov(noa,nub,nub,noa)
                  real(kind=8), intent(in) :: H2B_vovo(nob,nua,nua,nob)
                  integer, allocatable :: idx_table(:,:,:,:), loc_arr(:,:), block_off(:)
                  integer(kind=8), allocatable :: block_key(:)
                  integer :: kdims(6), nblock
                  logical :: kchain(6)
                  real(kind=8), allocatable :: t3_amps_buff(:), t4_amps_buff(:)
                  integer, allocatable :: t3_excits_buff(:,:), t4_excits_buff(:,:)
                  real(kind=8) :: hmatel, hmatel1, hmatel2, hmatel3, hmatel4
                  integer :: a, b, c, d, e, f, g, h, i, j, k, l, m, n, o, p, idet, jdet, idx, nloc
                  resid = 0.0d0

                  !!!! -0.0833333 * H.ab.vooo(dmlk) * T.bbb(abcijm) -> dcbalkji
                  ! allocate and copy over t3d arrays
                  allocate(t3_amps_buff(n3bbb),t3_excits_buff(n3bbb,6))
                  t3_amps_buff(:) = t3d_amps(:)
                  t3_excits_buff(:,:) = t3d_excits(:,:)
                  ! allocate sorting arrays (can be reused for each permutation)
                  kdims(1:5) = (/nub,nub,nub,nob,nob/)
                  kchain(1:5) = (/.false.,.true.,.true.,.false.,.true./)
                  !!! ABCIJ LOOP !!!
                  call sort_pspace(t3_excits_buff, t3_amps_buff, n3bbb, 5, (/1,2,3,4,5/), kdims, kchain, nblock, block_key, block_off)
                  !!!! BEGIN OMP PARALLEL SECTION !!!!
                  !$omp parallel shared(resid,&
                  !$omp t4d_excits,t3_excits_buff,&
                  !$omp t4d_amps,t3_amps_buff,&
                  !$omp nblock,block_key,block_off,kdims,kchain,&
                  !$omp H2B_vooo,&
                  !$omp noa,nua,nob,nub,n4abbb),&
                  !$omp private(hmatel,a,b,c,d,i,j,k,l,e,f,m,n,o,idet,jdet,&
                  !$omp idx)
                  !$omp do schedule(static)
                  do idet = 1, n4abbb
                     a = t4d_excits(idet,1); b = t4d_excits(idet,2); c = t4d_excits(idet,3); d = t4d_excits(idet,4);
                     i = t4d_excits(idet,5); j = t4d_excits(idet,6); k = t4d_excits(idet,7); l = t4d_excits(idet,8);
                     ! (1)
                     idx = pspace_find(block_key, nblock, pspace_key((/b,c,d,j,k/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        o = t3_excits_buff(jdet,6);
                        ! compute < ijklabcd | h2b(vooo) | jkobcd >
                        !hmatel = -h2b_vooo(a,o,i,l)
                        hmatel = -h2b_vooo(o,a,i,l)
                        resid(idet) = resid(idet) + hmatel * t3_amps_buff(jdet)
                     end do
                     end if
                     ! (jl)
                     idx = pspace_find(block_key, nblock, pspace_key((/b,c,d,k,l/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        o = t3_excits_buff(jdet,6);
                        ! compute < ijklabcd | h2b(vooo) | klobcd >
                        !hmatel = -h2b_vooo(a,o,i,j)
                        hmatel = -h2b_vooo(o,a,i,j)
                        resid(idet) = resid(idet) + hmatel * t3_amps_buff(jdet)
                     end do
                     end if
                     ! (kl)
                     idx = pspace_find(block_key, nblock, pspace_key((/b,c,d,j,l/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        o = t3_excits_buff(jdet,6);
                        ! compute < ijklabcd | h2b(vooo) | jlobcd >
                        !hmatel = h2b_vooo(a,o,i,k)
                        hmatel = h2b_vooo(o,a,i,k)
                        resid(idet) = resid(idet) + hmatel * t3_amps_buff(jdet)
                     end do
                     end if
                  end do
                  !$omp end do
                  !$omp end parallel
                  !!!! END OMP PARALLEL SECTION !!!!
                  !!! ABCIK LOOP !!!
                  call sort_pspace(t3_excits_buff, t3_amps_buff, n3bbb, 5, (/1,2,3,4,6/), kdims, kchain, nblock, block_key, block_off)
                  !!!! BEGIN OMP PARALLEL SECTION !!!!
                  !$omp parallel shared(resid,&
                  !$omp t4d_excits,t3_excits_buff,&
                  !$omp t4d_amps,t3_amps_buff,&
                  !$omp nblock,block_key,block_off,kdims,kchain,&
                  !$omp H2B_vooo,&
                  !$omp noa,nua,nob,nub,n4abbb),&
                  !$omp private(hmatel,a,b,c,d,i,j,k,l,e,f,m,n,idet,jdet,&
                  !$omp idx)
                  !$omp do schedule(static)
                  do idet = 1, n4abbb
                     a = t4d_excits(idet,1); b = t4d_excits(idet,2); c = t4d_excits(idet,3); d = t4d_excits(idet,4);
                     i = t4d_excits(idet,5); j = t4d_excits(idet,6); k = t4d_excits(idet,7); l = t4d_excits(idet,8);
                     ! (1)
                     idx = pspace_find(block_key, nblock, pspace_key((/b,c,d,j,l/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        n = t3_excits_buff(jdet,5);
                        ! compute < ijklabcd | h2b(vooo) | jnlbcd >
                        !hmatel = -h2b_vooo(a,n,i,k)
                        hmatel = -h2b_vooo(n,a,i,k)
                        resid(idet) = resid(idet) + hmatel * t3_amps_buff(jdet)
                     end do
                     end if
                     ! (jk)
                     idx = pspace_find(block_key, nblock, pspace_key((/b,c,d,k,l/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        n = t3_excits_buff(jdet,5);
                        ! compute < ijklabcd | h2b(vooo) | knlbcd >
                        !hmatel = h2b_vooo(a,n,i,j)
                        hmatel = h2b_vooo(n,a,i,j)
                        resid(idet) = resid(idet) + hmatel * t3_amps_buff(jdet)
                     end do
                     end if
                     ! (kl)
                     idx = pspace_find(block_key, nblock, pspace_key((/b,c,d,j,k/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        n = t3_excits_buff(jdet,5);
                        ! compute < ijklabcd | h2b(vooo) | jnkbcd >
                        !hmatel = h2b_vooo(a,n,i,l)
