                     if (loc_arr(2,kdx) < loc_arr(1,kdx)) cycle
                     idet = loc_arr(1,kdx)
                     a = t4d_excits(idet,1); c = t4d_excits(idet,3); k = t4d_excits(idet,7); l = t4d_excits(idet,8);
                     IX = 0.0d0
                     do u = 1, nub
                        IX(:,:) = IX(:,:) + (-1d0 * t2c(c,u,k,l)) * H2B_vovv_1203(:,:,a,u)
