                  call release_sort_workspace()
              end subroutine t4d_p_b3

              subroutine t4d_p_b2(resid,&
                                      t4d_amps, t4d_excits, t4c_amps, t4c_excits,&
                                      t4e_amps, t4e_excits, t2b, t2c,&
                                      H2B_voov_1023, H2C_oooo_1023, H2B_vovo_1023, H2B_oooo_1023,&
                                      H2C_voov_1023, V2C_oovv_1023, V2B_oovv_1023, H2B_ovvo_2013,&
                                      V2B_oovv_2013, V2A_oovv_3012, H2B_ovov_3012, H2C_voov_3012,&
                                      H2C_vvvv_3012, H2B_vvvv_3012, V2C_oovv_3012, V2B_oovv_3012,&
                                      V2B_oovv, V2A_oovv_1023, n4abbb, n4aabb,&
                                      n4bbbb, noa, nua, nob,&
                                      nub)
                  integer, intent(in) :: n4abbb, n4aabb, n4bbbb, noa, nua, nob, nub
                  real(kind=8), intent(inout) :: resid(n4abbb)
                  !f2py intent(in,out) :: resid(0:n4abbb-1)
                  real(kind=8), intent(inout) :: t4d_amps(n4abbb)
                  !f2py intent(in,out) :: t4d_amps(0:n4abbb-1)
                  integer, intent(inout) :: t4d_excits(n4abbb,8)
                  !f2py intent(in,out) :: t4d_excits(0:n4abbb-1,0:7)
                  real(kind=8), intent(in) :: t4c_amps(n4aabb)
                  integer, intent(in) :: t4c_excits(n4aabb,8)
                  real(kind=8), intent(in) :: t4e_amps(n4bbbb)
                  integer, intent(in) :: t4e_excits(n4bbbb,8)
                  real(kind=8), intent(in) :: t2b(nua,nub,noa,nob)
                  real(kind=8), intent(in) :: t2c(nub,nub,nob,nob)
                  real(kind=8), intent(in) :: H2B_voov_1023(nob,nua,noa,nub)
                  real(kind=8), intent(in) :: H2C_oooo_1023(nob,nob,nob,nob)
                  real(kind=8), intent(in) :: H2B_vovo_1023(nob,nua,nua,nob)
                  real(kind=8), intent(in) :: H2B_oooo_1023(nob,noa,noa,nob)
                  real(kind=8), intent(in) :: H2C_voov_1023(nob,nub,nob,nub)
                  real(kind=8), intent(in) :: V2C_oovv_1023(nob,nob,nub,nub)
                  real(kind=8), intent(in) :: V2B_oovv_1023(nob,noa,nua,nub)
                  real(kind=8), intent(in) :: H2B_ovvo_2013(nua,noa,nub,nob)
                  real(kind=8), intent(in) :: V2B_oovv_2013(nua,noa,nob,nub)
                  real(kind=8), intent(in) :: V2A_oovv_3012(nua,noa,noa,nua)
                  real(kind=8), intent(in) :: H2B_ovov_3012(nub,noa,nub,noa)
                  real(kind=8), intent(in) :: H2C_voov_3012(nub,nub,nob,nob)
                  real(kind=8), intent(in) :: H2C_vvvv_3012(nub,nub,nub,nub)
                  real(kind=8), intent(in) :: H2B_vvvv_3012(nub,nua,nub,nua)
                  real(kind=8), intent(in) :: V2C_oovv_3012(nub,nob,nob,nub)
                  real(kind=8), intent(in) :: V2B_oovv_3012(nub,noa,nob,nua)
                  real(kind=8), intent(in) :: V2B_oovv(noa,nob,nua,nub)
                  real(kind=8), intent(in) :: V2A_oovv_1023(noa,noa,nua,nua)
                  integer, allocatable :: idx_table(:,:,:,:), loc_arr(:,:), toff(:), soff(:)
                  integer(kind=8), allocatable :: tkey(:), skey(:)
                  integer :: tdims(8), sdims(8), tnblk, snblk
                  logical :: tchain(8), schain(8)
                  real(kind=8), allocatable :: bt4c_amps(:)
                  integer, allocatable :: bt4c_excits(:,:)
                  real(kind=8), allocatable :: bt4d_amps(:)
                  integer, allocatable :: bt4d_excits(:,:)
                  real(kind=8), allocatable :: bt4e_amps(:)
                  integer, allocatable :: bt4e_excits(:,:)
                  real(kind=8), allocatable :: IX(:)
                  real(kind=8) :: val
                  integer :: a, b, c, d, i, j, k, l, x, y, u, v, w, z, r, s, t, g, h
                  integer :: r1, r2, r3, r4, r5, r6, idet, jdet, kdx, idx, nloc
                  allocate(bt4c_amps(n4aabb),bt4c_excits(n4aabb,8))
                  bt4c_amps(:) = t4c_amps(:)
                  bt4c_excits(:,:) = t4c_excits(:,:)
                  allocate(bt4d_amps(n4abbb),bt4d_excits(n4abbb,8))
                  bt4d_amps(:) = t4d_amps(:)
                  bt4d_excits(:,:) = t4d_excits(:,:)
                  allocate(bt4e_amps(n4bbbb),bt4e_excits(n4bbbb,8))
                  bt4e_amps(:) = t4e_amps(:)
                  bt4e_excits(:,:) = t4e_excits(:,:)


                  !!!! 25 passes on T4 sorted by columns (1,2,5,6,7)
                  tdims(1:5) = (/nua,nub,noa,nob,nob/)
                  tchain(1:5) = (/.false.,.false.,.false.,.false.,.true./)
                  call sort_pspace(t4d_excits, t4d_amps, n4abbb, 5, (/1,2,5,6,7/), tdims, tchain, tnblk, tkey, toff, resid)
                  ! -0.25 * W(axibkj) * tbb(dclx), q = (a,b,i,j,k), sign +1
                  !$omp parallel default(shared) private(IX,val,a,b,c,d,i,j,k,l,x,y,u,v,w,z,r,s,t,g,h,idet,jdet,kdx,idx)
                  allocate(IX(nob))
                  !$omp do schedule(dynamic)
                  do kdx = 1, tnblk
                     if (toff(kdx+1)-1 < toff(kdx)) cycle
                     idet = toff(kdx)
                     a = t4d_excits(idet,1); b = t4d_excits(idet,2); i = t4d_excits(idet,5); j = t4d_excits(idet,6); k = t4d_excits(idet,7);
                     IX = 0.0d0
                     do u = 1, nub
                        IX(:) = IX(:) + (1d0 * t2c(b,u,j,k)) * H2B_voov_1023(:,a,i,u)
                     end do
                     do idet = toff(kdx), toff(kdx+1)-1
                        c = t4d_excits(idet,3); d = t4d_excits(idet,4); l = t4d_excits(idet,8);
                        val = 0.0d0
                        do x = 1, nob
                           val = val + IX(x) * t2c(d,c,l,x)
                        end do
                        resid(idet) = resid(idet) - 1d0 * val
                     end do
                  end do
                  !$omp end do
                  deallocate(IX)
                  !$omp end parallel
                  ! +0.25 * W(xlkadi) * tbb(cbxj), q = (a,b,i,j,k), sign +1
                  !$omp parallel default(shared) private(IX,val,a,b,c,d,i,j,k,l,x,y,u,v,w,z,r,s,t,g,h,idet,jdet,kdx,idx)
                  allocate(IX(nob))
                  !$omp do schedule(dynamic)
                  do kdx = 1, tnblk
                     if (toff(kdx+1)-1 < toff(kdx)) cycle
                     idet = toff(kdx)
                     a = t4d_excits(idet,1); b = t4d_excits(idet,2); i = t4d_excits(idet,5); j = t4d_excits(idet,6); k = t4d_excits(idet,7);
                     IX = 0.0d0
                     do u = 1, nob
                        IX(:) = IX(:) + (-1d0 * t2b(a,b,i,u)) * H2C_oooo_1023(:,u,j,k)
                     end do
                     do idet = toff(kdx), toff(kdx+1)-1
                        c = t4d_excits(idet,3); d = t4d_excits(idet,4); l = t4d_excits(idet,8);
                        val = 0.0d0
                        do x = 1, nob
                           val = val + IX(x) * t2c(d,c,x,l)
                        end do
                        resid(idet) = resid(idet) + 1d0 * val
                     end do
                  end do
                  !$omp end do
                  deallocate(IX)
                  !$omp end parallel
                  ! -0.5 * W(axkbij) * tbb(dclx), q = (a,b,i,j,k), sign -1
                  !$omp parallel default(shared) private(IX,val,a,b,c,d,i,j,k,l,x,y,u,v,w,z,r,s,t,g,h,idet,jdet,kdx,idx)
                  allocate(IX(nob))
                  !$omp do schedule(dynamic)
                  do kdx = 1, tnblk
                     if (toff(kdx+1)-1 < toff(kdx)) cycle
                     idet = toff(kdx)
                     a = t4d_excits(idet,1); b = t4d_excits(idet,2); i = t4d_excits(idet,5); j = t4d_excits(idet,6); k = t4d_excits(idet,7);
                     IX = 0.0d0
                     do u = 1, nua
                        IX(:) = IX(:) + (1d0 * t2b(u,b,i,k)) * H2B_vovo_1023(:,a,u,j)
                     end do
                     do idet = toff(kdx), toff(kdx+1)-1
                        c = t4d_excits(idet,3); d = t4d_excits(idet,4); l = t4d_excits(idet,8);
                        val = 0.0d0
                        do x = 1, nob
                           val = val + IX(x) * t2c(d,c,l,x)
                        end do
                        resid(idet) = resid(idet) + 1d0 * val
                     end do
                  end do
                  !$omp end do
