              subroutine update_t4e_p(resid,&
                                      t4e_amps, t4e_excits, t4d_amps, t4d_excits,&
                                      t3c_amps, t3c_excits, t3d_amps, t3d_excits,&
                                      t2c, H1B_oo, H1B_vv, H2B_oovo,&
                                      H2B_ovvo, H2B_ovvv, H2C_oooo, H2C_ooov,&
                                      H2C_vooo, H2C_voov, H2C_vovv, H2C_vvov,&
                                      H2C_vvvv, H2A_oovv, H2B_oovv, H2C_oovv,&
                                      fA_oo, fA_vv, fB_oo, fB_vv,&
                                      shift, n4bbbb, n3abb, n3bbb,&
                                      n4abbb, noa, nua, nob,&
                                      nub)

                  integer, intent(in) :: n4bbbb, n3abb, n3bbb, n4abbb, noa, nua, nob, nub
                  real(kind=8), intent(in) :: t4d_amps(n4abbb)
                  integer, intent(in) :: t4d_excits(n4abbb,8)
                  real(kind=8), intent(in) :: t3c_amps(n3abb)
                  integer, intent(in) :: t3c_excits(n3abb,6)
                  real(kind=8), intent(in) :: t3d_amps(n3bbb)
                  integer, intent(in) :: t3d_excits(n3bbb,6)
                  real(kind=8), intent(in) :: t2c(nub,nub,nob,nob)
                  real(kind=8), intent(in) :: H1B_oo(nob,nob)
                  real(kind=8), intent(in) :: H1B_vv(nub,nub)
                  real(kind=8), intent(in) :: H2B_oovo(noa,nob,nua,nob)
                  real(kind=8), intent(in) :: H2B_ovvo(noa,nub,nua,nob)
                  real(kind=8), intent(in) :: H2B_ovvv(noa,nub,nua,nub)
                  real(kind=8), intent(in) :: H2C_oooo(nob,nob,nob,nob)
                  real(kind=8), intent(in) :: H2C_ooov(nob,nob,nob,nub)
                  real(kind=8), intent(in) :: H2C_vooo(nub,nob,nob,nob)
                  real(kind=8), intent(in) :: H2C_voov(nub,nob,nob,nub)
                  real(kind=8), intent(in) :: H2C_vovv(nub,nob,nub,nub)
                  real(kind=8), intent(in) :: H2C_vvov(nub,nub,nob,nub)
                  real(kind=8), intent(in) :: H2C_vvvv(nub,nub,nub,nub)
                  real(kind=8), intent(in) :: H2A_oovv(noa,noa,nua,nua)
                  real(kind=8), intent(in) :: H2B_oovv(noa,nob,nua,nub)
                  real(kind=8), intent(in) :: H2C_oovv(nob,nob,nub,nub)
                  real(kind=8), intent(in) :: fA_oo(noa,noa), fA_vv(nua,nua), fB_oo(nob,nob), fB_vv(nub,nub), shift

                  integer, intent(inout) :: t4e_excits(n4bbbb,8)
                  !f2py intent(in,out) :: t4e_excits(0:n4bbbb-1,0:7)
                  real(kind=8), intent(inout) :: t4e_amps(n4bbbb)
                  !f2py intent(in,out) :: t4e_amps(0:n4bbbb-1)
                  real(kind=8), intent(out) :: resid(n4bbbb)

                  real(kind=8), allocatable :: h2c_vvov_3012(:,:,:,:)
                  real(kind=8), allocatable :: h2c_vooo_1023(:,:,:,:)
                  real(kind=8), allocatable :: h2c_vvvv_2301(:,:,:,:)
                  real(kind=8), allocatable :: h1b_vv_10(:,:)
                  real(kind=8), allocatable :: h2c_voov_1302(:,:,:,:)
                  real(kind=8), allocatable :: h2b_ovvo_0213(:,:,:,:)
                  real(kind=8), allocatable :: h2c_vovv_2301(:,:,:,:)
                  real(kind=8), allocatable :: h2c_ooov_1302(:,:,:,:)
                  real(kind=8), allocatable :: h2c_vovv_1302(:,:,:,:)
                  real(kind=8), allocatable :: h2c_oovv_1302(:,:,:,:)
                  real(kind=8), allocatable :: h2b_oovv_1302(:,:,:,:)
                  real(kind=8), allocatable :: h2b_oovo_0213(:,:,:,:)
                  real(kind=8), allocatable :: h2b_ovvv_0213(:,:,:,:)
                  real(kind=8), allocatable :: h2a_oovv_1302(:,:,:,:)
                  real(kind=8), allocatable :: h2c_voov_1023(:,:,:,:)
                  real(kind=8), allocatable :: h2c_oooo_1023(:,:,:,:)
                  real(kind=8), allocatable :: h2c_oovv_1023(:,:,:,:)
                  real(kind=8), allocatable :: h2b_oovv_1023(:,:,:,:)
                  real(kind=8), allocatable :: h2c_vvvv_3012(:,:,:,:)
                  real(kind=8), allocatable :: h2c_oovv_3012(:,:,:,:)
                  real(kind=8), allocatable :: h2b_oovv_3012(:,:,:,:)
                  integer :: idet, p1, p2, p3, p4, a, b, c, d, i, j, k, l
                  real(kind=8) :: denom

                  ! integrals in the layouts of the sparse kernels (summed or block indices first)
                  allocate(h2c_vvov_3012(nub,nub,nub,nob))
                  do p4 = 1, nob
                     do p3 = 1, nub
                        do p2 = 1, nub
                           do p1 = 1, nub
                              h2c_vvov_3012(p1,p2,p3,p4) = H2C_vvov(p2,p3,p4,p1)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2c_vooo_1023(nob,nub,nob,nob))
                  do p4 = 1, nob
                     do p3 = 1, nob
                        do p2 = 1, nub
                           do p1 = 1, nob
                              h2c_vooo_1023(p1,p2,p3,p4) = H2C_vooo(p2,p1,p3,p4)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2c_vvvv_2301(nub,nub,nub,nub))
                  do p4 = 1, nub
                     do p3 = 1, nub
                        do p2 = 1, nub
                           do p1 = 1, nub
                              h2c_vvvv_2301(p1,p2,p3,p4) = H2C_vvvv(p3,p4,p1,p2)
                           end do
                        end do
                     end do
                  end do
                  allocate(h1b_vv_10(nub,nub))
                  do p2 = 1, nub
                     do p1 = 1, nub
                        h1b_vv_10(p1,p2) = H1B_vv(p2,p1)
                     end do
                  end do
                  allocate(h2c_voov_1302(nob,nub,nub,nob))
                  do p4 = 1, nob
                     do p3 = 1, nub
                        do p2 = 1, nub
                           do p1 = 1, nob
                              h2c_voov_1302(p1,p2,p3,p4) = H2C_voov(p3,p1,p4,p2)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2b_ovvo_0213(noa,nua,nub,nob))
                  do p4 = 1, nob
                     do p3 = 1, nub
                        do p2 = 1, nua
                           do p1 = 1, noa
                              h2b_ovvo_0213(p1,p2,p3,p4) = H2B_ovvo(p1,p3,p2,p4)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2c_vovv_2301(nub,nub,nub,nob))
                  do p4 = 1, nob
                     do p3 = 1, nub
                        do p2 = 1, nub
                           do p1 = 1, nub
                              h2c_vovv_2301(p1,p2,p3,p4) = H2C_vovv(p3,p4,p1,p2)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2c_ooov_1302(nob,nub,nob,nob))
                  do p4 = 1, nob
                     do p3 = 1, nob
                        do p2 = 1, nub
                           do p1 = 1, nob
                              h2c_ooov_1302(p1,p2,p3,p4) = H2C_ooov(p3,p1,p4,p2)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2c_vovv_1302(nob,nub,nub,nub))
                  do p4 = 1, nub
                     do p3 = 1, nub
                        do p2 = 1, nub
                           do p1 = 1, nob
                              h2c_vovv_1302(p1,p2,p3,p4) = H2C_vovv(p3,p1,p4,p2)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2c_oovv_1302(nob,nub,nob,nub))
                  do p4 = 1, nub
                     do p3 = 1, nob
                        do p2 = 1, nub
                           do p1 = 1, nob
                              h2c_oovv_1302(p1,p2,p3,p4) = H2C_oovv(p3,p1,p4,p2)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2b_oovv_1302(nob,nub,noa,nua))
                  do p4 = 1, nua
                     do p3 = 1, noa
                        do p2 = 1, nub
                           do p1 = 1, nob
                              h2b_oovv_1302(p1,p2,p3,p4) = H2B_oovv(p3,p1,p4,p2)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2b_oovo_0213(noa,nua,nob,nob))
                  do p4 = 1, nob
                     do p3 = 1, nob
                        do p2 = 1, nua
                           do p1 = 1, noa
                              h2b_oovo_0213(p1,p2,p3,p4) = H2B_oovo(p1,p3,p2,p4)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2b_ovvv_0213(noa,nua,nub,nub))
                  do p4 = 1, nub
                     do p3 = 1, nub
                        do p2 = 1, nua
                           do p1 = 1, noa
                              h2b_ovvv_0213(p1,p2,p3,p4) = H2B_ovvv(p1,p3,p2,p4)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2a_oovv_1302(noa,nua,noa,nua))
                  do p4 = 1, nua
                     do p3 = 1, noa
                        do p2 = 1, nua
                           do p1 = 1, noa
                              h2a_oovv_1302(p1,p2,p3,p4) = H2A_oovv(p3,p1,p4,p2)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2c_voov_1023(nob,nub,nob,nub))
                  do p4 = 1, nub
                     do p3 = 1, nob
                        do p2 = 1, nub
                           do p1 = 1, nob
                              h2c_voov_1023(p1,p2,p3,p4) = H2C_voov(p2,p1,p3,p4)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2c_oooo_1023(nob,nob,nob,nob))
                  do p4 = 1, nob
                     do p3 = 1, nob
                        do p2 = 1, nob
                           do p1 = 1, nob
                              h2c_oooo_1023(p1,p2,p3,p4) = H2C_oooo(p2,p1,p3,p4)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2c_oovv_1023(nob,nob,nub,nub))
                  do p4 = 1, nub
                     do p3 = 1, nub
                        do p2 = 1, nob
                           do p1 = 1, nob
                              h2c_oovv_1023(p1,p2,p3,p4) = H2C_oovv(p2,p1,p3,p4)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2b_oovv_1023(nob,noa,nua,nub))
                  do p4 = 1, nub
                     do p3 = 1, nua
                        do p2 = 1, noa
                           do p1 = 1, nob
                              h2b_oovv_1023(p1,p2,p3,p4) = H2B_oovv(p2,p1,p3,p4)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2c_vvvv_3012(nub,nub,nub,nub))
                  do p4 = 1, nub
                     do p3 = 1, nub
                        do p2 = 1, nub
                           do p1 = 1, nub
                              h2c_vvvv_3012(p1,p2,p3,p4) = H2C_vvvv(p2,p3,p4,p1)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2c_oovv_3012(nub,nob,nob,nub))
                  do p4 = 1, nub
                     do p3 = 1, nob
                        do p2 = 1, nob
                           do p1 = 1, nub
                              h2c_oovv_3012(p1,p2,p3,p4) = H2C_oovv(p2,p3,p4,p1)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2b_oovv_3012(nub,noa,nob,nua))
                  do p4 = 1, nua
                     do p3 = 1, nob
                        do p2 = 1, noa
                           do p1 = 1, nub
                              h2b_oovv_3012(p1,p2,p3,p4) = H2B_oovv(p2,p3,p4,p1)
                           end do
                        end do
                     end do
                  end do

                  ! (H(2) * T3 + H(2) * T4)_C linear terms
                  call t4e_p_lin(resid, t4e_amps, t4e_excits, t3d_amps, t3d_excits, t4d_amps,&
                                 t4d_excits, h2c_vvov_3012, h2c_vooo_1023, H2C_oooo, H1B_oo, h2c_vvvv_2301,&
                                 h1b_vv_10, h2c_voov_1302, h2b_ovvo_0213, n4bbbb, n3bbb, n4abbb,&
                                 noa, nua, nob, nub)
                  ! (I(T2, T3) * T3)_C terms
                  call t4e_p_b3(resid, t4e_amps, t4e_excits, t3c_amps, t3c_excits, t3d_amps,&
                                t3d_excits, t2c, H2C_ooov, H2C_oovv, h2c_vovv_2301, h2c_ooov_1302,&
                                h2c_vovv_1302, h2c_oovv_1302, h2b_oovv_1302, h2b_oovo_0213, h2b_ovvv_0213, h2a_oovv_1302,&
                                n4bbbb, n3abb, n3bbb, noa, nua, nob,&
                                nub)
                  ! (I(T2, T4) * T2)_C and (H * T2 * T2)_C terms
                  call t4e_p_b2(resid, t4e_amps, t4e_excits, t4d_amps, t4d_excits, t2c,&
                                h2c_voov_1023, h2c_oooo_1023, h2c_oovv_1023, h2b_oovv_1023, h2c_vvvv_3012, h2c_oovv_3012,&
                                h2b_oovv_3012, n4bbbb, n4abbb, noa, nua, nob,&
                                nub)
                  deallocate(h2c_vvov_3012)
                  deallocate(h2c_vooo_1023)
                  deallocate(h2c_vvvv_2301)
                  deallocate(h1b_vv_10)
                  deallocate(h2c_voov_1302)
                  deallocate(h2b_ovvo_0213)
                  deallocate(h2c_vovv_2301)
                  deallocate(h2c_ooov_1302)
                  deallocate(h2c_vovv_1302)
                  deallocate(h2c_oovv_1302)
                  deallocate(h2b_oovv_1302)
                  deallocate(h2b_oovo_0213)
                  deallocate(h2b_ovvv_0213)
                  deallocate(h2a_oovv_1302)
                  deallocate(h2c_voov_1023)
                  deallocate(h2c_oooo_1023)
                  deallocate(h2c_oovv_1023)
                  deallocate(h2b_oovv_1023)
                  deallocate(h2c_vvvv_3012)
                  deallocate(h2c_oovv_3012)
                  deallocate(h2b_oovv_3012)

                  ! Update t4 vector
                  !$omp parallel shared(resid,t4e_excits,t4e_amps,fA_oo,fA_vv,fB_oo,fB_vv,n4bbbb,shift),&
                  !$omp private(idet,a,b,c,d,i,j,k,l,denom)
                  !$omp do schedule(static)
                  do idet = 1, n4bbbb
                      a = t4e_excits(idet,1); b = t4e_excits(idet,2); c = t4e_excits(idet,3); d = t4e_excits(idet,4);
                      i = t4e_excits(idet,5); j = t4e_excits(idet,6); k = t4e_excits(idet,7); l = t4e_excits(idet,8);
                      denom = fB_oo(i,i) + fB_oo(j,j) + fB_oo(k,k) + fB_oo(l,l) - fB_vv(a,a) - fB_vv(b,b) - fB_vv(c,c) - fB_vv(d,d)
                      resid(idet) = resid(idet)/(denom - shift)
                      t4e_amps(idet) = t4e_amps(idet) + resid(idet)
                  end do
                  !$omp end do
                  !$omp end parallel

              end subroutine update_t4e_p

              subroutine t4e_p_lin(resid,&
                                      t4e_amps, t4e_excits, t3d_amps, t3d_excits,&
                                      t4d_amps, t4d_excits, H2C_vvov, H2C_vooo,&
                                      H2C_oooo, H1B_oo, H2C_vvvv, H1B_vv,&
                                      H2C_voov, H2B_ovvo, n4bbbb, n3bbb,&
                                      n4abbb, noa, nua, nob,&
                                      nub)
                  integer, intent(in) :: n4bbbb, n3bbb, n4abbb, noa, nua, nob, nub
                  real(kind=8), intent(out) :: resid(n4bbbb)
                  real(kind=8), intent(inout) :: t4e_amps(n4bbbb)
                  !f2py intent(in,out) :: t4e_amps(0:n4bbbb-1)
                  integer, intent(inout) :: t4e_excits(n4bbbb,8)
                  !f2py intent(in,out) :: t4e_excits(0:n4bbbb-1,0:8-1)
                  real(kind=8), intent(in) :: t3d_amps(n3bbb)
                  integer, intent(in) :: t3d_excits(n3bbb,6)
                  real(kind=8), intent(in) :: t4d_amps(n4abbb)
                  integer, intent(in) :: t4d_excits(n4abbb,8)
                  real(kind=8), intent(in) :: H2C_vvov(nub,nub,nub,nob)
                  real(kind=8), intent(in) :: H2C_vooo(nob,nub,nob,nob)
                  real(kind=8), intent(in) :: H2C_oooo(nob,nob,nob,nob)
                  real(kind=8), intent(in) :: H1B_oo(nob,nob)
                  real(kind=8), intent(in) :: H2C_vvvv(nub,nub,nub,nub)
                  real(kind=8), intent(in) :: H1B_vv(nub,nub)
                  real(kind=8), intent(in) :: H2C_voov(nob,nub,nub,nob)
                  real(kind=8), intent(in) :: H2B_ovvo(noa,nua,nub,nob)
                  integer, allocatable :: idx_table(:,:,:,:), loc_arr(:,:), block_off(:)
                  integer(kind=8), allocatable :: block_key(:)
                  integer :: kdims(6), nblock
                  logical :: kchain(6)
                  real(kind=8), allocatable :: t3_amps_buff(:), t4_amps_buff(:)
                  integer, allocatable :: t3_excits_buff(:,:), t4_excits_buff(:,:)
                  real(kind=8) :: hmatel, hmatel1, hmatel2, hmatel3, hmatel4
                  integer :: a, b, c, d, e, f, g, h, i, j, k, l, m, n, o, p, idet, jdet, idx, nloc
                  resid = 0.0d0

                  !!!! +0.0416667 * H.bb.vvov(cdke) * T.bbb(abeijl) -> abcdijkl
                  ! allocate and copy over t3d arrays
                  allocate(t3_amps_buff(n3bbb),t3_excits_buff(n3bbb,6))
                  t3_amps_buff(:) = t3d_amps(:)
                  t3_excits_buff(:,:) = t3d_excits(:,:)
                  ! allocate sorting arrays (can be reused for each permutation)
                  kdims(1:5) = (/nub,nub,nob,nob,nob/)
                  kchain(1:5) = (/.false.,.true.,.false.,.true.,.true./)
                  !!! ABIJK LOOP !!!
                  call sort_pspace(t3_excits_buff, t3_amps_buff, n3bbb, 5, (/1,2,4,5,6/), kdims, kchain, nblock, block_key, block_off)
                  !!!! BEGIN OMP PARALLEL SECTION !!!!
                  !$omp parallel shared(resid,&
                  !$omp t4e_excits,t3_excits_buff,&
                  !$omp t4e_amps,t3_amps_buff,&
                  !$omp nblock,block_key,block_off,kdims,kchain,&
                  !$omp H2C_vvov,&
                  !$omp nob,nub,n4bbbb),&
                  !$omp private(hmatel,a,b,c,d,i,j,k,l,e,f,m,n,g,idet,jdet,&
                  !$omp idx)
                  !$omp do schedule(static)
                  do idet = 1, n4bbbb
                     a = t4e_excits(idet,1); b = t4e_excits(idet,2); c = t4e_excits(idet,3); d = t4e_excits(idet,4);
                     i = t4e_excits(idet,5); j = t4e_excits(idet,6); k = t4e_excits(idet,7); l = t4e_excits(idet,8);
                     ! (1)
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,i,j,l/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        g = t3_excits_buff(jdet,3);
                        ! compute < ijklabcd | h2c(vvov) | ijlabg >
                        !hmatel = h2c_vvov(c,d,k,g)
                        hmatel = h2c_vvov(g,c,d,k)
                        resid(idet) = resid(idet) + hmatel * t3_amps_buff(jdet)
                     end do
                     end if
                     ! (ac)
                     idx = pspace_find(block_key, nblock, pspace_key((/b,c,i,j,l/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        g = t3_excits_buff(jdet,3);
                        ! compute < ijklabcd | h2c(vvov) | ijlbcg >
                        !hmatel = h2c_vvov(a,d,k,g)
                        hmatel = h2c_vvov(g,a,d,k)
                        resid(idet) = resid(idet) + hmatel * t3_amps_buff(jdet)
                     end do
                     end if
                     ! (ac)(bd)
                     idx = pspace_find(block_key, nblock, pspace_key((/c,d,i,j,l/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        g = t3_excits_buff(jdet,3);
                        ! compute < ijklabcd | h2c(vvov) | ijlcdg >
                        !hmatel = h2c_vvov(a,b,k,g)
                        hmatel = h2c_vvov(g,a,b,k)
                        resid(idet) = resid(idet) + hmatel * t3_amps_buff(jdet)
                     end do
                     end if
                     ! (ad)
                     idx = pspace_find(block_key, nblock, pspace_key((/b,d,i,j,l/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        g = t3_excits_buff(jdet,3);
                        ! compute < ijklabcd | h2c(vvov) | ijlbdg >
                        !hmatel = -h2c_vvov(a,c,k,g)
