              subroutine t4e_p_b3(resid,&
                                      t4e_amps, t4e_excits, t3c_amps, t3c_excits,&
                                      t3d_amps, t3d_excits, t2c, H2C_ooov,&
                                      V2C_oovv, H2C_vovv_2301, H2C_ooov_1302, H2C_vovv_1302,&
