                  real(kind=8), intent(in) :: t3d_amps(n3bbb)
                  integer, intent(in) :: t3d_excits(n3bbb,6)
                  real(kind=8), intent(in) :: t2c(nub,nub,nob,nob)
                  real(kind=8), intent(in) :: H2C_ooov(nob,nob,nob,nub)
